INSERT OR REPLACE INTO Language_en_US (Tag, Text)
SELECT 'TXT_KEY_POP_CSTATE_UCS_INFO_TAB', 		'' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_KEMZHIKET', 			'Kemzhiket' UNION ALL -- replaces Clermont
SELECT 'TXT_KEY_CITYSTATE_KEMZHIKET_ADJ', 			'Yenisei Kyrgyz' UNION ALL
SELECT 'TXT_KEY_CIV5_KEMZHIKET_TEXT', 				'The Yenisei Kyrgyz were an ancient Turkic people who inhabited the upper Yenisei River region in southern Siberia (modern-day Tuva and Khakassia) and played a significant role in Central Asian history between the 6th and 13th centuries CE. First mentioned in Chinese chronicles during the Tang dynasty, they were known for their nomadic pastoral lifestyle, skilled horsemanship, and distinctive runic inscriptions written in the Old Turkic script. In the 9th century, under their leader Ajo Khan, the Yenisei Kyrgyz rose to prominence by overthrowing the Uyghur Khaganate (840 CE) and establishing a powerful khaganate that stretched across parts of Mongolia and Siberia. Although their influence waned with the expansion of the Mongol Empire in the 13th century, the Yenisei Kyrgyz are regarded as the ancestors of the modern Kyrgyz people of Central Asia. Their legacy endures in linguistic, cultural, and historical traditions that bridge the early Turkic steppe civilizations with the later formation of the Kyrgyz nation.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_HONDURAS', 			'Tegucigalpa' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_HONDURAS_ADJ', 			'Honduran' UNION ALL
SELECT 'TXT_KEY_CIV5_HONDURAS_TEXT', 				'Honduras, located in Central America between Guatemala, El Salvador, and Nicaragua, with coastlines on both the Caribbean Sea and the Pacific Ocean, has a rich and complex history shaped by Indigenous civilizations, colonization, and modern nation-building. Before European contact, it was home to advanced cultures such as the Maya, whose ruins at Copán stand as a major archaeological and cultural treasure. Spanish explorer Christopher Columbus landed on its coast in 1502, and by 1524 the region was fully incorporated into the Spanish Empire, becoming a center for mining and colonial administration. After gaining independence from Spain in 1821, Honduras joined and later separated from the short-lived Federal Republic of Central America, establishing itself as a republic in 1838. The 20th century saw periods of political instability, foreign corporate influence, particularly from U.S. banana companies, and military rule. Today, Honduras is a democratic nation marked by vibrant cultural traditions, natural beauty, and ongoing efforts to address social and economic challenges while preserving its diverse Indigenous and Afro-Caribbean heritage.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_PARIHAKA', 			'Parihaka' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_PARIHAKA_ADJ', 			'Maori' UNION ALL
SELECT 'TXT_KEY_CIV5_PARIHAKA_TEXT', 				'The Maori are the Indigenous Polynesian people of Aotearoa (New Zealand), whose ancestors arrived by canoe voyages from eastern Polynesia around the 13th century, developing a rich culture deeply rooted in the land, sea, and spiritual connection to ancestry (whakapapa). Over centuries, they established distinct tribal groups (iwi) and subtribes (hapu), building complex social systems, fortified villages (pa), and traditions of carving, tattooing (ta moko), and oral storytelling. Maori society encountered major change after the arrival of Europeans in the 18th century, culminating in the 1840 signing of the Treaty of Waitangi between Maori chiefs and the British Crown, a founding yet contested document in New Zealand''s history. Subsequent land loss, conflict, and colonization disrupted Maori life, but the 20th and 21st centuries have seen a powerful cultural and political resurgence. Today, Maori identity, language (te reo Maori), and customs (tikanga) are central to New Zealand''s national character and continue to shape its evolving bicultural society.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SARATOV', 			'Saratov' UNION ALL -- replaces Armagh
SELECT 'TXT_KEY_CITYSTATE_SARATOV_ADJ', 			'Kalmyk' UNION ALL
SELECT 'TXT_KEY_CIV5_SARATOV_TEXT', 				'The Kalmyks are a Mongolic people who migrated from the Dzungarian region of Central Asia to the lower Volga River area in the 17th century, becoming the only traditionally Buddhist population in Europe. Descended from the Oirat Mongols, they established the Kalmyk Khanate in 1630 under Kho Orluk, pledging allegiance to the Russian Tsar while maintaining autonomy. Their society was based on nomadic pastoralism, rich oral traditions, and Tibetan Buddhism. In the late 18th century, Russian imperial expansion curtailed their independence, and in 1771 a large portion of the Kalmyks attempted to return to Dzungaria, a perilous migration known as the "Great Return", in which most perished. Those who remained were absorbed into the Russian Empire but retained their distinct identity. During the Soviet era, the Kalmyks faced repression, including mass deportation during World War II. Today, they primarily inhabit the Republic of Kalmykia in southwestern Russia, where they continue to revive their language, religion, and cultural heritage as Europe''s westernmost Buddhist community.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MUSCAT', 				'Muscat' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MUSCAT_ADJ', 				'Omani' UNION ALL
SELECT 'TXT_KEY_CIV5_MUSCAT_TEXT', 					'The trade flowing through Muscat has been its lifeblood for at least two millennia. Nestled against the foothillls of the Al Hajar mountains, Ptolemy called it the Hidden Port ("Cryptus Portus") as early as the 1st Century. Unfortunately the city was not hidden well enough - its prime location at the mouth of the Persian Gulf has long since made it a tempting target for conquest. [NEWLINE][NEWLINE]Over the centuries Muscat''s port has flown many banners: Sassanid, Arabian (under which it converted to Islam in the 7th Century), Abbasid, Seljuk, and Persian, to name a few. In the early 16th Century, a Portuguese admiral sought to open trade relations - with cannons, burning most of Muscat to the ground. It was rebuilt and remained under Portuguese rule until 1650, when the Omani forced them out and reclaimed the port city.[NEWLINE][NEWLINE]Muscat has long come to conflict with the interior tribes of Oman, most commonly over self-governance. Amidst one such period of turmoil in the 18th Century rose the Al Bu Sa''id dynasty, which has remained unbroken through modern times. Today, an extensively modernized Muscat serves as Oman''s capital and remains an important trading port.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_GRANADA', 			'Granada' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_GRANADA_ADJ', 			'Moorish' UNION ALL
SELECT 'TXT_KEY_CIV5_GRANADA_TEXT', 				'In the 8th Century the Umayyad Caliphate spread through the Iberian Peninsula, rapidly conquering Visigothic Hispania. Granada, a fortified settlement in what is now southern Spain, was swept up in the invasion. In time to come (the late 15th Century, to be exact) its surrender to the Catholic Monarchs ("Los Reyes Católicos") would end the Reconquista of Andalusia-but for three quarters of a millennium, Granada belonged to the Moors.[NEWLINE][NEWLINE]Located at the base of the Sierra Nevada range, Granada had the misfortune of being nearly indefensible due to its location on a low-lying plain. Its Moorish rulers quickly realized this and transferred their seat of power to the more defensible foothills overlooking the town. Part of their plans involved the building of alcazars, one of which would in later years be renovated into the beautiful Alhambra.[NEWLINE][NEWLINE]Granada''s Moorish masters shifted through the centuries. The Almohad replaced the Almoravids, who had themselves succeeded the remnants of the Umayyad. The city''s fortunes changed again in the 13th Century with the Nasrid dynasty, whose alliance with the Catholic kingdom of Castile led to the Emirate of Granada. Direct access to trade centers in sub-Saharan Africa bought Granada freedom from the Reconquista - for a time.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_NAN_MADOL', 			'Nan Madol' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_NAN_MADOL_ADJ', 			'Nan Madol' UNION ALL
SELECT 'TXT_KEY_CIV5_NAN_MADOL_TEXT', 				'Nan Madol is an ancient archaeological site located on the eastern coast of Pohnpei in the Federated States of Micronesia, often called the "Venice of the Pacific" due to its network of canals separating artificial islets. Constructed between the 12th and 16th centuries CE by the Saudeleur dynasty, it served as the ceremonial and political center of the island, housing royal compounds, temples, and tombs. The site is renowned for its megalithic architecture, with massive basalt columns carefully stacked without mortar, reflecting sophisticated engineering and social organization. Nan Madol was central to the Saudeleur rulers'' control over Pohnpei, symbolizing both religious authority and political power. The city declined in the early 17th century due to internal unrest and the collapse of the Saudeleur dynasty, but its impressive ruins remain a testament to the ingenuity and cultural complexity of ancient Micronesian civilization.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SEORABEOL', 			'Seorabeol' UNION ALL -- replaces Aberffraw
SELECT 'TXT_KEY_CITYSTATE_SEORABEOL_ADJ', 			'Sillan' UNION ALL
SELECT 'TXT_KEY_CIV5_SEORABEOL_TEXT', 				'The Silla Kingdom was one of the Three Kingdoms of ancient Korea, founded in 57 BCE on the southeastern Korean Peninsula and lasting until 935 CE. Initially a small tribal state, Silla gradually centralized power under its royal lineage, adopting Buddhism in the 6th century and fostering a flourishing culture of art, architecture, and scholarship. Under King Munmu and his predecessors, Silla allied with Tang China to conquer its rivals Baekje and Goguryeo in the 7th century, achieving the first unified Korean state in 668 CE, known as Unified Silla. This period saw remarkable cultural and technological achievements, including the creation of Buddhist temples such as Bulguksa and the Seokguram Grotto. However, internal strife and aristocratic power struggles eventually weakened the kingdom, leading to its fall to the emerging Goryeo dynasty in 935. The legacy of Silla endures as a defining chapter in Korean history, remembered for its unification of the peninsula and its golden age of cultural and artistic development.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MUISCA', 				'Suamox' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MUISCA_ADJ', 				'Muiscan' UNION ALL
SELECT 'TXT_KEY_CIV5_MUISCA_TEXT', 					'The Muisca were an advanced Indigenous civilization that flourished on the high plains of the Eastern Andes in present-day Colombia, primarily in the Bogotá and Tunja regions, from around 600 to 1600 CE. As one of the major pre-Columbian cultures of South America, alongside the Inca, Maya, and Aztec, the Muisca developed a sophisticated society based on agriculture, trade, and metallurgy, excelling in the production of fine goldwork that inspired the legend of El Dorado. Organized into a loose confederation of chiefdoms led by rulers known as the zipa (in Bacatá, modern Bogotá) and the zaque (in Hunza, modern Tunja), the Muisca maintained complex social, religious, and political systems centered around the worship of deities such as Sué (the sun god) and Chía (the moon goddess). Spanish conquistadors led by Gonzalo Jiménez de Quesada subjugated the Muisca in the 1530s, leading to the collapse of their political structures. Despite colonization, Muisca descendants continue to preserve elements of their language, traditions, and identity, maintaining a vital link to Colombia''s pre-Hispanic heritage.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_NOGAI', 				'Saray-Juk' UNION ALL -- replaces Sparta
SELECT 'TXT_KEY_CITYSTATE_NOGAI_ADJ', 				'Nogai' UNION ALL
SELECT 'TXT_KEY_CIV5_NOGAI_TEXT', 					'The Nogai Horde was a confederation founded by the Nogais that occupied the Pontic-Caspian steppe from about 1500 until they were pushed west by the Kalmyks and south by the Russians in the 17th century. The Mongol tribe called the Manghuds constituted a core of the Nogai Horde. [NEWLINE][NEWLINE]In the 13th century, the leader of the Golden Horde, Nogai Khan, a direct descendant of Genghis Khan through Jochi, formed an army of the Manghits joined by numerous Turkic tribes. A century later the Nogays were led by Edigu, a commander of Manghit paternal origin and Jochid maternal origin, who founded the Nogai dynasty. [NEWLINE][NEWLINE]In 1557, Nogai Nur-al-Din Qazi Mirza quarreled with Ismael Beg and founded the Lesser Nogai Horde on the steppe of the North Caucasus. The Nogais north of the Caspian were thereafter called the Great Nogai Horde. In the early 17th century, the Horde broke down further under the onslaught of the Kalmyks. [NEWLINE][NEWLINE]The Nogais north of the Black Sea were nominally subject to the Crimean Khanate rather than the Nogai Bey. They were divided into the following groups: Budjak (from the Danube to the Dniester), Yedisan (from the Dniester to the Bug), Jamboyluk (Bug to Crimea), Yedickul (north of Crimea) and Kuban. In particular, the Yedisans are mentioned as a distinct group, and in various locations.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_CHEVAK', 				'Chevak' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_CHEVAK_ADJ', 				'Yup''ik' UNION ALL
SELECT 'TXT_KEY_CIV5_CHEVAK_TEXT', 					'The Yup''ik people, indigenous to Alaska and the Russian Far East, have a rich history deeply connected to the Arctic and sub-Arctic environments. Their ancestors, part of the larger Eskimo-Aleut group, have lived in the region for thousands of years, developing a semi-nomadic lifestyle centered on subsistence activities like fishing, hunting sea mammals, and gathering. They are renowned for their sophisticated tools, kayaks, and traditional qasgiq (communal houses). The Yup''ik worldview emphasizes a harmonious relationship with nature, reflected in their oral traditions, dances, and ceremonies. [NEWLINE]By about 3,000 years ago the progenitors of the Yupiit had settled along the coastal areas of what would become western Alaska, with migrations up the coastal rivers -notably the Yukon and Kuskokwim- around 1400 C.E., eventually reaching as far upriver as Paimiut on the Yukon and Crow Village (Tulukarugmiut) on the Kuskokwim. [NEWLINE]Contact with Europeans in the 18th and 19th centuries brought significant changes, including the introduction of Christianity, new trade goods, and challenges like disease and cultural disruption. Despite these influences, the Yup''ik people have preserved much of their language, traditions, and knowledge, remaining one of the largest indigenous groups in Alaska today.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SANTO_DOMINGO', 		'Santo Domingo' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SANTO_DOMINGO_ADJ', 		'Dominican' UNION ALL
SELECT 'TXT_KEY_CIV5_SANTO_DOMINGO_TEXT', 			'The Dominican Republic, occupying the eastern two-thirds of the island of Hispaniola in the Caribbean, has a complex history shaped by Indigenous, European, and African influences. Before European contact, the island was home to the Taíno people, who lived in organized chiefdoms. Christopher Columbus landed there in 1492, establishing Santo Domingo in 1498, the first permanent European settlement in the Americas and the seat of Spain''s early colonial empire in the New World. The colony became a center of Spanish expansion but later declined as Spain shifted focus elsewhere, leading to periods of foreign occupation, including French control of the western third (now Haiti). The Dominican Republic declared independence from Haiti in 1844 under Juan Pablo Duarte and later endured brief annexation by Spain and several political upheavals. Today, it is a democratic nation known for its vibrant culture, music, and economy, blending its Indigenous, African, and Spanish heritages. Although it was never a formal "kingdom", its historical evolution reflects centuries of colonial and national transformation in the Caribbean.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MANAGUA', 			'Managua' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MANAGUA_ADJ', 			'Nicaraguan' UNION ALL
SELECT 'TXT_KEY_CIV5_MANAGUA_TEXT', 				'Nicaragua, the largest country in Central America, is bordered by Honduras to the north and Costa Rica to the south, with coastlines on both the Pacific Ocean and the Caribbean Sea. Its name derives from the indigenous Nicarao people and the Spanish word "agua", meaning water, reflecting its many lakes and rivers, including the vast Lake Nicaragua. Before Spanish colonization in the 16th century, the region was inhabited by diverse Indigenous groups. After gaining independence from Spain in 1821 and later from the Central American Federation in 1838, Nicaragua experienced long periods of political instability, dictatorship, and foreign intervention, most notably U.S. involvement in the early 20th century. The Somoza family ruled from 1936 to 1979 until the Sandinista revolution overthrew them, ushering in a socialist government that later faced a U.S.-backed Contra war in the 1980s. Since then, Nicaragua has transitioned to a nominal democracy, though recent years under President Daniel Ortega have seen increasing authoritarianism, repression of dissent, and strained relations with Western nations.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ODENSO', 				'Helsinki' UNION ALL -- VP5 conflict
SELECT 'TXT_KEY_CITYSTATE_ODENSO_ADJ', 				'Finnish' UNION ALL
SELECT 'TXT_KEY_CIV5_ODENSO_TEXT', 					'Helsinki, the capital and largest city of Finland, lies on the northern shore of the Gulf of Finland, facing the Baltic Sea. Founded in 1550 by King Gustav I of Sweden as a trading post to rival Tallinn, it remained a small town until the early 19th century, when it gained prominence after Finland was annexed by Russia. In 1812, the Russian Empire moved the Finnish capital from Turku to Helsinki to strengthen control and proximity to St. Petersburg, prompting rapid growth and neoclassical urban development under architect Carl Ludvig Engel. Following Finland''s independence from Russia in 1917, Helsinki became the heart of the new republic, evolving into a modern European capital known for its functionalist architecture, design heritage, and high quality of life. Today, Helsinki is a vibrant, forward-looking city blending Nordic tradition with innovation, sustainability, and a strong maritime culture.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_YANGCHENG', 			'Yangcheng' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_YANGCHENG_ADJ', 			'Xia' UNION ALL
SELECT 'TXT_KEY_CIV5_YANGCHENG_TEXT', 				'Considered the first capital of the Xia Dynasty, it was built upon the Yin River and held until the fall of their dynasty. The Xia Dynasty, traditionally regarded as China''s first dynasty, is said to have ruled from around 2070 to 1600 BCE, marking the beginning of Chinese civilization. According to ancient texts like the Records of the Grand Historian by Sima Qian, it was founded by the legendary Emperor Yu the Great, who earned his authority by controlling the floods of the Yellow River and establishing hereditary rule. The Xia are described as having developed early forms of bronze casting, agriculture, and social organization, laying the groundwork for later Chinese dynasties. However, because there are no definitive written records from the period and much of the evidence is drawn from later historical accounts and possible archaeological correlations with the Erlitou culture, the Xia''s historical existence remains partly mythic and debated among scholars.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_PHANOTEUS', 			'Phanoteus' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_PHANOTEUS_ADJ', 			'Phocian' UNION ALL
SELECT 'TXT_KEY_CIV5_PHANOTEUS_TEXT', 				'Phanoteus (or Phanote) was an ancient Greek city located in the region of Epirus, specifically in the territory of the Chaonians near the modern area of northwest Greece. It was strategically positioned along important routes connecting Epirus to Thessaly and central Greece, giving it both military and trade significance. Historical references to Phanoteus are limited, but it is mentioned by classical authors such as Polybius and Livy, particularly in the context of Hellenistic warfare. The city was fortified and played a role during the wars between the Macedonians, Romans, and Epiriots in the 3rd and 2nd centuries BCE. Eventually, like many smaller Epirote cities, Phanoteus declined following the Roman conquest of Epirus in 167 BCE, when the region was devastated and many settlements were depopulated or absorbed into the Roman provincial system.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DOUALA', 				'Douala' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DOUALA_ADJ', 				'Cameroonian' UNION ALL
SELECT 'TXT_KEY_CIV5_DOUALA_TEXT', 					'Cameroon, located in Central Africa and often called "Africa in miniature" for its cultural and geographic diversity, borders Nigeria, Chad, the Central African Republic, Equatorial Guinea, Gabon, and the Republic of the Congo, with a coastline along the Atlantic Ocean. The area was home to various kingdoms and ethnic groups long before European contact, including the Sao civilization near Lake Chad. Portuguese explorers arrived in the 15th century, naming the region Rio dos Camarões ("River of Prawns"), from which the modern name derives. In the late 19th century, Cameroon became a German colony (Kamerun), but after Germany''s defeat in World War I, it was divided between France and Britain under League of Nations mandates. French Cameroon gained independence in 1960, followed by British Southern Cameroons in 1961, forming the Federal Republic of Cameroon. Since then, the country has been ruled largely by two presidents, Ahmadou Ahidjo and Paul Biya, and while relatively stable compared to some neighbors, Cameroon has faced political tension, corruption, and a violent Anglophone separatist conflict in recent years.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ZAZZAU', 				'Zazzau' UNION ALL -- replaces Ambracia
SELECT 'TXT_KEY_CITYSTATE_ZAZZAU_ADJ', 				'Zazzau' UNION ALL
SELECT 'TXT_KEY_CIV5_ZAZZAU_TEXT', 					'The Kingdom of Zazzau, also known as Zaria, was one of the Hausa city-states in what is now northern Nigeria, with its origins dating back to the 11th century. Established by the Hausa people, Zazzau became a major center of trade, agriculture, and culture in the region, benefiting from its strategic location on trans-Saharan trade routes. It was renowned for its production of slaves, cotton, and grain, which were exchanged for salt, horses, and luxury goods from North Africa and beyond. Islam was introduced to Zazzau in the 15th century, profoundly influencing its political and cultural life, as rulers and elites embraced the religion while incorporating it into governance and education.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DJIBOUTI', 			'Djibouti' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DJIBOUTI_ADJ', 			'Djiboutian' UNION ALL
SELECT 'TXT_KEY_CIV5_DJIBOUTI_TEXT', 				'Djibouti, a small but strategically vital country in the Horn of Africa, lies between Eritrea, Ethiopia, and Somalia, with coastlines along the Red Sea and the Gulf of Aden. Its territory has long been inhabited by Afar and Somali (Issa) peoples, who were part of ancient trade networks linking Africa, Arabia, and the Indian Ocean. The area came under Islamic influence by the 9th century through Arab traders. In the late 19th century, France established control, creating the colony of French Somaliland in 1896, later renamed the French Territory of the Afars and the Issas. Djibouti gained independence from France in 1977, with Hassan Gouled Aptidon as its first president. Since then, the country has remained politically stable under a tightly controlled system, now led by President Ismail Omar Guelleh. Its economy and geopolitical importance stem from its deep-water port and location at the entrance to the Red Sea, hosting several foreign military bases and serving as a key hub for trade and shipping between Africa, the Middle East, and Asia.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DODOMA', 				'Dar es Salaam' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DODOMA_ADJ', 				'Tanzanian' UNION ALL
SELECT 'TXT_KEY_CIV5_DODOMA_TEXT', 					'Located on the Swahili coast, Dar es Salaam (Arabic: "Abode of Peace") is Tanzania''s largest city and most prominent centre for arts, fashion, media, film, television, and finance. With a population of over six million people, Dar is the largest city in East Africa and the sixth-largest in Africa.[NEWLINE][NEWLINE]Dar es Salaam was founded in 1862 by Majid bin Said, the first Sultan of Zanzibar, on the site of the village of Mzizima ("healthy town" in Swahili). It remained only a small port until the German East Africa Company established a station there in 1887. In 1905, the city was the starting point for the Central Line railroad, which facilitated the town''s growth and industrial development. Dar es Salaam served as the capital of German East Africa (1891-1916), Tanganyika (1961-64), and Tanzania (1964-74). In 1974, Dodoma was designated as new capital, although the transfer of official functions was officially completed in 1996. [NEWLINE][NEWLINE]Buildings in Dar es Salaam often reflect the city''s colonial past and display a rich mix of architectural styles, incorporating Swahili, British, German, and Asian traditions. Post-World War II modernization and expansion brought contemporary multistory buildings, including a hospital complex, a technical institute, and a high court. Educational facilities include the University of Dar es Salaam (1961), several libraries and research institutes, and the National Museum.[NEWLINE][NEWLINE]Dar es Salaam''s natural, nearly landlocked harbour is the outlet for most of mainland Tanzania''s agricultural and mineral exports and in addition serves the nearby land-locked countries of Uganda, Rwanda, Burundi, the Democratic Republic of the Congo, Zambia, and Malawi. It is also a transit port for the Congo River, whose navigable tributary, the Lualaba, can be reached by rail.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_FAYA', 				'N''Djamena' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_FAYA_ADJ', 				'Chadian' UNION ALL
SELECT 'TXT_KEY_CIV5_FAYA_TEXT', 					'Chad is a landlocked country in north-central Africa, bordered by Libya, Sudan, the Central African Republic, Cameroon, Nigeria, and Niger. Its geography ranges from desert in the north to arid Sahel and fertile savannas in the south. The region has been inhabited for thousands of years, with ancient civilizations such as the Sao people flourishing around Lake Chad. In the late 19th century, France colonized the area, making it part of French Equatorial Africa in 1900. Chad gained independence on August 11, 1960, but its postcolonial history has been marked by political instability, civil wars, and ethnic divisions between the largely Muslim north and Christian or animist south. Despite these challenges, Chad has gradually strengthened its government and economy, largely through oil production, while facing ongoing issues such as poverty, regional conflict, and environmental pressures on Lake Chad.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_KIGALI', 				'Kigali' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_KIGALI_ADJ', 				'Rwandan' UNION ALL
SELECT 'TXT_KEY_CIV5_KIGALI_TEXT', 					'Kigali is the capital city of Rwanda being initially developed by the Kingdom of Rwanda in the 14th century, and has been its historical capital in modern times. Rwanda, a small, landlocked country in East-Central Africa, is known as the "Land of a Thousand Hills" for its lush, mountainous terrain. Historically, it was home to the Twa, Hutu, and Tutsi peoples, who shared language and culture but developed distinct social roles over centuries under a centralized monarchy. In the late 19th century, Rwanda became part of German East Africa and later a Belgian-administered territory after World War I, during which colonial policies deepened ethnic divisions by favoring the Tutsi minority. After gaining independence in 1962, tensions between Hutu and Tutsi groups led to cycles of violence, culminating in the 1994 genocide, when extremist Hutu militias killed around 800,000 Tutsi and moderate Hutu in just 100 days. The genocide ended when the Tutsi-led Rwandan Patriotic Front (RPF), led by Paul Kagame, took power. Since then, Rwanda has achieved remarkable political stability and economic growth, pursuing reconciliation and modernization, though its government faces criticism for authoritarian practices and limits on political freedoms.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_LEVUKA', 				'Levuka' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_LEVUKA_ADJ', 				'Fijian' UNION ALL
SELECT 'TXT_KEY_CIV5_LEVUKA_TEXT', 					'Levuka is a port town on the east coast of Ovalau island and capital of Lomaiviti province in the South Pacific country of Fiji. Settled by a U.S. adventurer in 1822, the area was the centre of a cotton boom during the American Civil War (1861-65), when world cotton supplies were disrupted.[NEWLINE][NEWLINE]When the first modern nation state of Fiji, the Kingdom of Fiji, was founded in 1871, Seru Epenisa Cakobau was crowned King at Levuka. After Fiji was annexed as a British colony in 1874, Levuka remained the capital until 1877, when the administration was moved to Suva, although the move was not made official until 1882.[NEWLINE][NEWLINE]It is now the centre of Fiji''s tuna-processing industry, supplied mainly by Japanese, South Korean, and Taiwanese fishing boats. The town''s 19th-century architecture is still largely intact, and in 2013 Levuka was designated a UNESCO World Heritage site for its cultural and historical value.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_QUELIMANE', 			'Quelimane' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_QUELIMANE_ADJ', 			'Swahili' UNION ALL
SELECT 'TXT_KEY_CIV5_QUELIMANE_TEXT', 				'Quelimane is a historic port city in central Mozambique, located near the mouth of the Rio dos Bons Sinais on the Indian Ocean. Founded in the early 16th century by Portuguese traders and missionaries, it became one of the oldest colonial settlements in East Africa. Originally a Swahili-Arab trading post, Quelimane grew into a key point in the Portuguese trade network for ivory, gold, and later slaves, serving as a gateway to the interior regions such as the Zambezi Valley. In the 19th and early 20th centuries, it developed as a center for sugar, copra, and tea exports, linked to plantations in the fertile surrounding lands. During Mozambique''s struggle for independence from Portugal (1964-1975), Quelimane was a site of political unrest, and after independence, it became the capital of Zambezia Province. Today, the city remains an important regional port and commercial hub, known for its tropical climate, mangrove-lined waterways, and proximity to natural reserves and beaches.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_OYO', 				'Òyó' UNION ALL -- replaces Freetown
SELECT 'TXT_KEY_CITYSTATE_OYO_ADJ', 				'Òyó' UNION ALL
SELECT 'TXT_KEY_CIV5_OYO_TEXT', 					'The Oyo Empire was a Yoruba empire in West Africa. It was located in present-day southern Benin and western Nigeria (including the South West zone and the western half of the North Central zone). The empire grew to become the largest Yoruba-speaking state through the organizational and administrative efforts of the Yoruba people, trade, as well as the military use of cavalry. The Oyo Empire was one of the most politically important states in Western Africa from the mid-17th to the late 18th century and held sway not only over most of the other kingdoms in Yorubaland, but also over nearby African states, notably the Fon Kingdom of Dahomey in the modern Republic of Benin on its west.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DETTAH', 				'Dettah' UNION ALL -- replaces Brooklands
SELECT 'TXT_KEY_CITYSTATE_DETTAH_ADJ', 				'Yellowknife' UNION ALL
SELECT 'TXT_KEY_CIV5_DETTAH_TEXT', 					'The Yellowknives, or T''atsaot''ine, are an Indigenous people of northern Canada, traditionally inhabiting the region around the Great Slave Lake in what is now the Northwest Territories. Their name derives from the distinctive yellowish copper tools they historically crafted and traded, highlighting their expertise in metallurgy and resource use. The Yellowknives lived as hunter-gatherers, relying on caribou, fish, and other local wildlife, and maintained seasonal movements to follow game and access resources. They were closely connected to neighboring Dene groups, sharing language and cultural practices, while also engaging in trade networks that extended across the subarctic. European contact in the 18th and 19th centuries, particularly through the fur trade, brought both new opportunities and challenges, including disease and shifts in traditional lifestyles. Today, the Yellowknives continue to preserve their language, cultural traditions, and land rights, playing an active role in regional governance and Indigenous advocacy.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_TAIWAN', 				'Taipei' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_TAIWAN_ADJ', 				'Taiwanese' UNION ALL
SELECT 'TXT_KEY_CIV5_TAIWAN_TEXT', 					'Taipei, the capital city of Taiwan (officially the Republic of China), is a vibrant metropolis located in the northern part of the island, surrounded by mountains and bisected by the Tamsui River. It serves as Taiwan''s political, economic, and cultural center, known for its modern skyline dominated by the iconic Taipei 101, bustling night markets, and rich blend of traditional and contemporary influences. Historically, the area was settled by Han Chinese immigrants during the 18th century under Qing rule and later became a major administrative center. After Japan took control of Taiwan in 1895, Taipei developed rapidly with modern infrastructure and urban planning. Following World War II and Taiwan''s return to Chinese rule, Taipei became the capital of the Republic of China in 1949 after the Nationalist government retreated from mainland China. Today, Taipei stands as a global city celebrated for its democracy, technology sector, cuisine, and dynamic cultural life. Much of the surrounding area continues to be inhabited by several Formosan indigenous groups, creating a rich cultural fabric distinct from mainland China''s domination by Han Chinese influence.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_OC_EO', 				'Óc Eo' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_OC_EO_ADJ', 				'Funanese' UNION ALL
SELECT 'TXT_KEY_CIV5_OC_EO_TEXT', 					'Funan was an ancient state in Cambodia that arose in the 1st century ad and was incorporated into the state of Chenla in the 6th century. Funan (perhaps a Chinese transcription of pnom, "mountain") was the first important Hinduized kingdom in southeast Asia. It covered portions of what are now Vietnam, Thailand, and Cambodia. Funan had trade relations with India as well as China, to whose emperor the people of Funan sent tribute between the 3rd and 6th centuries.[NEWLINE][NEWLINE]Funan reached the apex of its power under the 3rd-century king Fan Shiman, also known as Srei Meara. Fan Shiman expanded his empire''s navy and improved the Funanese bureaucracy, creating a quasi-feudal pattern that left local customs and identities largely intact, particularly in the empire''s further reaches. Fan Shiman and his successors also sent ambassadors to China and India to regulate sea trade. The kingdom likely accelerated the process of Indianization of Southeast Asia. Later kingdoms of Southeast Asia such as Chenla may have emulated the Funanese court. The Funanese established a strong system of mercantilism and commercial monopolies that would become a pattern for empires in the region.[NEWLINE][NEWLINE]Funan''s dependence on maritime trade is seen as a cause for the beginning of Funan''s downfall. Their coastal ports allowed trade with foreign regions that funnelled goods to the north and coastal populations. However, the shift in maritime trade to Sumatra, the rise in the Srivijaya trade empire, and the taking of trade routes all throughout Southeast Asia by China, leads to economic instability in the south, and forces politics and economy northward. Funan was superseded and absorbed in the 6th century by the Khmer polity of the Chenla Kingdom.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_THIMPHU', 			'Thimphu' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_THIMPHU_ADJ', 			'Bhutanese' UNION ALL
SELECT 'TXT_KEY_CIV5_THIMPHU_TEXT', 				'Since 1955 Thimphu is the capital of Bhutan, a small, landlocked kingdom nestled in the eastern Himalayas between China and India, renowned for its stunning mountain landscapes, rich Buddhist culture. Historically, Bhutan was unified in the 17th century under the leadership of Zhabdrung Ngawang Namgyal, who established a dual system of governance combining religious and civil authority. The Wangchuck dynasty came to power in 1907, founding a hereditary monarchy that continues today. For much of its history, Bhutan remained isolated to preserve its traditions, only gradually opening to the outside world in the latter half of the 20th century. In 2008, Bhutan transitioned peacefully to a constitutional monarchy and held its first democratic elections. The country is widely admired for its unique development philosophy of Gross National Happiness, balancing modernization with cultural preservation and sustainable growth.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ANDORRA', 			'Andorra' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ANDORRA_ADJ', 			'Andorran' UNION ALL
SELECT 'TXT_KEY_CIV5_ANDORRA_TEXT', 				'Lying on the southern slopes of the Pyrenees, the Principality of Andorra consists of a cluster of mountain valleys whose streams form the Valira River. Andorra''s independence is traditionally ascribed to Charlemagne, who recovered the region from the Muslims in 803 CE. It was placed under the joint suzerainty of the French counts of Foix and the Spanish bishops of Urgel in 1278, and it was subsequently governed jointly by the Spanish bishop of Urgel and the French head of state. This feudal system of government, the last in Europe, continued until 1993, when a constitution was adopted that transferred most of the coprinces'' powers to the Andorran General Council, which is elected by universal suffrage.[NEWLINE][NEWLINE]Andorra has long and a strong affinity with Catalonia; its institutions are based in Catalonian law, and it is part of the diocese of Urgel (Spain).[NEWLINE][NEWLINE]The traditional economy was based on sheep raising, but tourism grew in importance since the 1950s and became central to Andorra''s economy by the early 21st century.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_CANOSSA', 			'Canossa' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_CANOSSA_ADJ', 			'Tuscan' UNION ALL
SELECT 'TXT_KEY_CIV5_CANOSSA_TEXT', 				'Canossa is a historic castle and village located in the Emilia-Romagna region of northern Italy, famous for its dramatic role in medieval European history. Built around 940 by Atto Adalbert, the founder of the House of Attoni and first count of Canossa, it became the seat of Countess Matilda of Tuscany, one of the most powerful rulers of her time. Canossa gained lasting fame in 1077 during the Investiture Controversy, when Holy Roman Emperor Henry IV traveled there to seek forgiveness from Pope Gregory VII after being excommunicated. According to tradition, Henry stood barefoot in the snow for three days before being granted absolution-a powerful symbol of the struggle between secular and papal authority in medieval Europe. Though the castle was later destroyed in the 13th century, its ruins remain an enduring monument to this pivotal moment in Church-state relations.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_BEDULU', 				'Bedulu' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_BEDULU_ADJ', 				'Bali' UNION ALL
SELECT 'TXT_KEY_CIV5_BEDULU_TEXT', 					'Known as "the island of a thousand temples", Bali and its history are steeped in culture and religion, being one of the last bastions of Hinduism in Indonesia.[NEWLINE][NEWLINE]Bali was inhabited around 2000 BCE by Austronesian people who migrated originally from Southeast Asia and Oceania through Maritime Southeast Asia.[NEWLINE][NEWLINE]Culturally and linguistically, the Balinese are closely related to the people of the Indonesian archipelago, Malaysia, the Philippines and Oceania. Stone tools dating from this time have been found near the village of Cekik in the island''s west. Inscriptions from 896 and 911 do not mention a king, until 914, when Sri Kesarivarma is mentioned. They also reveal an independent Bali, with a distinct dialect, where Buddhism and Shivaism were practiced simultaneously.[NEWLINE][NEWLINE]Mpu Sindok''s great-granddaughter, Mahendradatta, married the Bali king Udayana Warmadewa around 989, giving birth to Airlangga around 1001. This marriage also brought more Hinduism and Javanese culture to Bali. Princess Sakalendukirana appeared in 1098. Suradhipa reigned from 1115 to 1119, and Jayasakti from 1146 until 1150. Jayapangus appears on inscriptions between 1178 and 1181, while Adikuntiketana and his son Paramesvara in 1204.[NEWLINE][NEWLINE]Balinese culture was strongly influenced by Indian, Chinese, and particularly Hindu culture, beginning around the 1st century AD. The name Bali dwipa ("Bali island") has been discovered from various inscriptions, including the Blanjong pillar inscription written by Sri Kesari Warmadewa in 914 and mentioning Walidwipa. It was during this time that the people developed their complex irrigation system, locally called subak, to grow rice in wet-field cultivation. Some religious and cultural traditions still practiced today can be traced to this period.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DALI', 				'Yangjumie' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DALI_ADJ', 				'Dali' UNION ALL
SELECT 'TXT_KEY_CIV5_DALI_TEXT', 					'The Kingdom of Dali, which meant "the great truth" or "the great administration", was a buddhist kingdom that played a vital role in south-east asia for nearly three centuries, from the 10th to the 13th century. It was a kingdom of piety, of many temples and giant stone pagodas, and was composed not of a homogeneous people but of many people and many tribes, the largest of which being the Bai and Yi.[NEWLINE][NEWLINE]The Dali kingdom was notable for its influence in preserving and spreading Buddhism. The royal Duan clan, like that of their Nanzhao predecessors before them were devout Buddhists, and they constructed large Buddhist temples around Dali and on the Shibaoshan Mountain. These soon became centers for Buddhist teaching. Here the Kings attempted to model themselves on the models of the Buddhist- divine kings of the nearby South East Asian kingdoms.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MULTAN', 				'Multan' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MULTAN_ADJ', 				'Ghaznavid' UNION ALL
SELECT 'TXT_KEY_CIV5_MULTAN_TEXT', 					'Multan is a city in the Punjab Province of Pakistan, and capital of Multan District. It is located in the southern part of the province, and is steeped in history. It has a population of over 3.8 million (according to 1998 census), making it the sixth largest city in Pakistan. It is built just east of the Chenab River, more or less in the geographic center of the country and about 966 km from Karachi.[NEWLINE][NEWLINE]Multan is known as the "City of Pirs and Shrines", and is a prosperous city of bazaars, mosques and superbly designed tombs. The Multan International Airport connects flights to major cities in Pakistan and to cities in the Persian Gulf. The city''s industries include metal working, flour, sugar, oil milling, textiles manufacturing, fertilizer, soap, and glass. Multan is also known for its handicrafts, especially pottery and enamel work.[NEWLINE][NEWLINE]One of the subcontinent''s oldest cities, Multan derives its name from an idol in the temple of the sun god, a shrine of the pre-Muslim period.[NEWLINE][NEWLINE]The city was conquered (c. 326 BC) by Alexander the Great, visited (AD 641) by the Chinese Buddhist scholar Hsüan-tsang, taken (8th cent.) by the Arabs, and captured by Muslim Turkish conqueror Mahmud of Ghazna in 1005 and by Timur in 1398. In the 16th and 17th century, Multan enjoyed peace under the rule of Mughal emperors. In 1818, the city was seized by Ranjit Singh, leader of the Sikhs. The British held it from 1848 until Pakistan achieved independence in 1947. Landmarks include an old fort containing the 14th-century tombs of two Muslim saints.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_BAGAN', 				'Pagan' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_BAGAN_ADJ', 				'Burmese' UNION ALL
SELECT 'TXT_KEY_CIV5_BAGAN_TEXT', 					'The kingdom grew out of a small 9th-century settlement at Pagan (present-day Bagan) by the Mranma/Burmans, who had recently entered the Irrawaddy valley from the Kingdom of Nanzhao. Over the next two hundred years, the small principality gradually grew to absorb its surrounding regions until the 1050s and 1060s when King Anawrahta founded the Pagan Empire, for the first time unifying under one polity the Irrawaddy valley and its periphery. By the late 12th century, Anawrahta''s successors had extended their influence farther to the south into the upper Malay peninsula, to the east at least to the Salween river, in the farther north to below the current China border, and to the west, in northern Arakan and the Chin Hills. In the 12th and 13th centuries, Pagan, alongside the Khmer Empire, was one of two main empires in mainland Southeast Asia. The kingdom went into decline in the mid-13th century as the continuous growth of tax-free religious wealth by the 1280s had severely affected the crown''s ability to retain the loyalty of courtiers and military servicemen. This ushered in a vicious circle of internal disorders and external challenges by the Arakanese, Mons, Mongols and Shans. Repeated Mongol invasions (1277-1301) toppled the four-century-old kingdom in 1287. The collapse was followed by 250 years of political fragmentation that lasted well into the 16th century.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_RISHIKESH', 			'Rishikesh' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_RISHIKESH_ADJ', 			'Garhwal' UNION ALL
SELECT 'TXT_KEY_CIV5_RISHIKESH_TEXT', 				'Known as the "Gateway to the Garhwal Himalayas" and "Yoga Capital of the World", Rishikesh, also spelt as Hrishikesh, is a city near Dehradun in Dehradun district of the Indian state Uttarakhand. It is situated on the right bank of the Ganges River and is a pilgrimage town for Hindus, with ancient sages and saints meditating here in search of higher knowledge. There are numerous temples and ashrams built along the banks of the river.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MUTITJULU', 			'Mutitjulu' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MUTITJULU_ADJ', 			'Anangu' UNION ALL
SELECT 'TXT_KEY_CIV5_MUTITJULU_TEXT', 				'"Anangu" is an umbrella term that describes several Australian Aboriginal groups who speak Western Desert languages; the term is most prominently used by the Pitjantjatjara and the Yankunytjatjara. The Western Desert languages have been described as covering more of Australia''s area than any other indigenous language.[NEWLINE][NEWLINE]Uluru and Kata Tjuta are sacred sites in the Anangu belief system, with eleven songlines passing through or near them. In 1979, the indigenous Central Land Council began a legal battle to lay claim to the Uluru-Kata Tjuta National Park; in 1985, the resulting settlement plan was implemented, which granted the Anangu a majority of the park''s Board of Management but still allowed tourists to visit the park.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ISKANWAYA', 			'Iskanwaya' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ISKANWAYA_ADJ', 			'Kallawaya' UNION ALL
SELECT 'TXT_KEY_CIV5_ISKANWAYA_TEXT', 				'Iskanwaya is a pre-Columbian sacred site, situated on a mountain ridge above the Llica River in Bolivia, 325 km north of La Paz. In its extension and its age Iskanwaya surpasses Machu Picchu in Peru, but it is less well preserved. The Iskanwaya ruins go back to the Mollo culture which predated the Inca civilization and whose people presumably built the constructions as early as 800 BC or in their prime cultural period from 1145 to 1425.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_TIWANAKU', 			'Tiwanaku' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_TIWANAKU_ADJ', 			'Tiwanaku' UNION ALL
SELECT 'TXT_KEY_CIV5_TIWANAKU_TEXT', 				'Tiwanaku (Spanish: Tiahuanaco and Tiahuanacu) is a Pre-Columbian archaeological site in western Bolivia, South America. It is the capital of an empire that extended into present-day Peru and Chile, flourishing from AD 300 to AD 1000. Tiwanaku is recognized by Andean scholars as one of the most important civilizations prior to the Inca Empire; it was the ritual and administrative capital of a major state power for approximately five hundred years. The ruins of the ancient city state are near the south-eastern shore of Lake Titicaca in the La Paz Department, Ingavi Province, Tiwanaku Municipality, about 72 km (45 mi) west of La Paz.49 while searching for the Inca capital Qullasuyu.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DANO', 				'Dano' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DANO_ADJ', 				'Dagara' UNION ALL
SELECT 'TXT_KEY_CIV5_DANO_TEXT', 					'Dano is the capital of the Ioba province in Burkina Faso. It is a small town with a market for weaving and pottery and is home to the Dagara people, whose traditional cosmology and ritual practices have persisted in spite of colonial Christian influences. These practices involve communing with elemental powers, channeling otherworldly beings, and performing divination with cowrie shells.[NEWLINE][NEWLINE]Dagara settlements occupy an area of about 3,500 square kilometres in south-western Burkina Faso and roughly the same area in north-western Ghana. The political and social organization of the Dagara is based on the "tengan system", i.e. a network of earth shrines that identify, delimit and spiritually protect Dagara communities.[NEWLINE][NEWLINE]Earth shrines are sacrificial sites, mostly consisting of stones under a large tree, which, according to the norms, must be erected by the first settlers to arrive in an area. At an earth shrine, sacrifices are made to the earth god held responsible for the fertility of women and the soil and for the peace of a particular area. Ritual control of the earth shrine simultaneously implies the right to distribute land and demand contributions for the required sacrifices. The earth priests, that is the sacrificers responsible for the shrine, thus distribute land to later settlers and regulate the access to other resources, sometimes in exchange for quite substantial gifts, and the late-comers must also request the earth priest''s permission to build houses and bury their dead.[NEWLINE][NEWLINE]In the non-centralized societies of the region, the earth priest, called tengansob or tindana, fulfilled the role of community elder, and during the pre-colonial period was the only local figure of authority. According to the tradition, the office of earth priest goes to the founder of the settlement or to one of his descendants within the same clan.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_KARYES', 				'Karyes' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_KARYES_ADJ', 				'Athonite' UNION ALL
SELECT 'TXT_KEY_CIV5_KARYES_TEXT', 					'The monastic community of Mount Athos is an Eastern Orthodox community of monks in Greece who hold the status of an autonomous region as well as the combined rights of a decentralized administration, a region and a municipality, with a territory encompassing the distal part of the Athos peninsula including Mount Athos. The bordering proximal part of the peninsula belongs to the regular Aristotelis community in Central Macedonia.[NEWLINE][NEWLINE]Organized monastic life began there in 963, when St. Athanasius the Athonite founded the first monastery. By 1400 there were 40 monasteries. Long regarded as the holy mountain of the Greek Orthodox Church, it was declared a theocratic republic in 1927. The Athonite monasteries feature a rich collection of well-preserved artifacts, rare books, ancient documents, and artworks of immense historical value, and Mount Athos has been listed as a World Heritage Site since 1988.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SGANG_GWAAY', 		'SGang Gwaay' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SGANG_GWAAY_ADJ', 		'Haida' UNION ALL
SELECT 'TXT_KEY_CIV5_SGANG_GWAAY_TEXT', 			'One of the many indigenous tribes of North America, the Haida stand apart as an island people. Related to the Tlingit and Tsimshian peoples, Haida society was organised around a clan system with stratified ranks of noble, commoner and slave. There were two major clans, determined through the maternal line. These clans were then subdivided into lineages.[NEWLINE][NEWLINE]The Haida are especially talented woodworkers, weavers and sailors; they have been credited with the first use of the totem pole. While their maritime behaviour lead them to establish many peaceful trade routes with the colonialists, locally they were feared warriors who practised slavery. For this reason they have often been called "the Vikings of North America".[NEWLINE][NEWLINE]Today the Haida reserves on the main island of Haida Gawaii have banded together to create the Council of the Haida Nation. They are experiencing a cultural resurgence.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_NYARYANA_MARQ', 		'Nyar''yana Marq' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_NYARYANA_MARQ_ADJ', 		'Nenet' UNION ALL
SELECT 'TXT_KEY_CIV5_NYARYANA_MARQ_TEXT', 			'The Nenets, also known as the Samoyeds, are an indigenous people in northern arctic Russia. According to the latest census in 2010, there are 44,857 Nenets in the Russian Federation, most of them living in the Yamalo-Nenets Autonomous Okrug and Nenets Autonomous Okrug. They speak either the Tundra or Forest varieties of Nenets. The literal morphs samo and yed in Russian convey the meaning "self-eater", which appears as derogatory. Therefore, the name Samoyed quickly went out of usage in the 20th century, and the people bear the name of Nenets, which means "man".' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ADEJE', 				'Adeje' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ADEJE_ADJ', 				'Guanche' UNION ALL
SELECT 'TXT_KEY_CIV5_ADEJE_TEXT', 					'The Guanches were the indigenous inhabitants of the Canary Islands in the Atlantic Ocean some 100 kilometres (60 mi) west of the North African coast. They spoke the Guanche language, which went extinct in the 17th century and is believed to have been related to Berber languages. It is believed that they may have arrived on the archipelago some time in the first millennium BC.[NEWLINE][NEWLINE]The Guanches were the only native people known to have lived in the Macaronesian archipelago region before the arrival of Europeans, as there is no accepted evidence that the other Macaronesian archipelagos (the Cape Verde Islands, Madeira and the Azores) were inhabited. After the Spanish conquest of the Canaries starting in the early 15th century, many natives were wiped out by the Spanish conquerors while the rest assimilated over time into the settler population and culture, although elements of their original culture survive within Canarian customs and traditions, such as Silbo (the whistled language of La Gomera Island), as well as some lexicon of Canarian Spanish.[NEWLINE][NEWLINE]Some scholars have classified the destruction of the Guanche people and culture as an early example of colonial genocide. In 2017, the first genome-wide data from the Guanches confirmed a North African origin and that they were genetically most similar to ancient North African Berber peoples of the nearby North African mainland.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_WOOTEI_NIICIE', 		'Wootei-niicie' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_WOOTEI_NIICIE_ADJ', 		'Arapaho' UNION ALL
SELECT 'TXT_KEY_CIV5_WOOTEI_NIICIE_TEXT', 			'Around 3,000 years ago, the ancestral Arapaho-speaking people, the Heeteinono''eino'' lived in the western Great Lakes region along the Red River Valley in what is classified as present-day Manitoba, Canada and Minnesota, United States. There the Arapaho were an agricultural people who grew crops, including maize.[NEWLINE][NEWLINE]Following European colonization in eastern Canada, together with the early Cheyenne people, the Hitesiino'', the Arapaho were forced to migrate westward onto the eastern Great Plains by the Ojibwe. They were numerous and powerful, having obtained guns from their French trading allies. The ancestors of the Arapaho people entered the Great Plains the western Great Lakes region sometime before 1700. During their early history on the plains, the Arapaho lived on the northern plains from the South Saskatchewan River in Canada south to Montana, Wyoming, and western South Dakota.[NEWLINE][NEWLINE]Before the Arapaho acquired horses, they used domestic dogs as pack animals to pull their travois. The Arapaho acquired horses in the early 1700s from other tribes, which changed their way of life. They became a nomadic people, using the horses as pack and riding animals. They could transport greater loads and travel more easily by horseback to hunt more easily and widely, increasing their success in hunting on the Plains. Gradually, the Arapaho moved farther south, split into the closely allied Northern and Southern Arapaho, and established a large joint territory spanning land in southern Montana, most of Wyoming, the Nebraska Panhandle, central and eastern Colorado, western Oklahoma, and extreme western Kansas.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DAKKAR', 				'Dakkar' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DAKKAR_ADJ', 				'Adalite' UNION ALL
SELECT 'TXT_KEY_CIV5_DAKKAR_TEXT', 					'Dakkar, also known as Dakar, or Deker, was a historical Muslim town located in present-day eastern Ethiopia. It served as the first capital of the Adal Sultanate (1415-1577) after its founding in the early 15th century by Sabr ad-Din III who reigned in the years 1415-1422. The Adal Sultanate was a powerful medieval Muslim state that flourished in the Horn of Africa, centered in what is now eastern Ethiopia, Djibouti, and northern Somalia. The sultanate played a key role in Red Sea and Indian Ocean trade, linking Africa with Arabia and Asia. It is most famous for its fierce conflict with the Ethiopian Empire during the early 16th century, led by the military commander Ahmad ibn Ibrahim al-Ghazi, also known as Ahmad "Gran". His campaigns nearly brought down the Ethiopian kingdom before his defeat and death in 1543. Though the sultanate eventually declined under internal and external pressures, it left a lasting legacy on the region''s political, cultural, and religious landscape.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_HONIARA', 			'Honiara' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_HONIARA_ADJ', 			'Solomonian' UNION ALL
SELECT 'TXT_KEY_CIV5_HONIARA_TEXT', 				'Honiara is the capital and largest city of Solomon Islands, located on the northwestern coast of Guadalcanal. The area gained global attention during World War II as the site of intense fighting between Allied and Japanese forces, particularly during the Guadalcanal campaign (1942-1943). After the war, Honiara was chosen to replace Tulagi as the national capital because of its better infrastructure and strategic location. Officially established as the capital in 1952, the city developed rapidly, becoming the country''s administrative, economic, and cultural hub. Today, Honiara is home to government institutions, a busy port, and a diverse population, while remnants of the war, such as memorials and relics, remain visible, linking its modern identity to its pivotal wartime past.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_KARASJOHKA', 			'Karasjohka' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_KARASJOHKA_ADJ', 			'Sami' UNION ALL
SELECT 'TXT_KEY_CIV5_KARASJOHKA_TEXT', 				'The Sami are an Indigenous people native to the northern regions of Norway, Sweden, Finland, and Russia''s Kola Peninsula, a cultural region known as Sápmi. With a history stretching back thousands of years, the Sami traditionally lived as semi-nomadic reindeer herders, fishers, and hunters, maintaining a close relationship with the Arctic environment. Their culture is rich in oral traditions, handicrafts (duodji), and distinctive clothing, such as the gákti. From the 19th century onward, they faced assimilation pressures and loss of land rights under national governments. In recent decades, however, there has been a strong cultural and political revival, with the establishment of Sami parliaments and increased recognition of their rights. Today, the Sami continue to balance modern life with the preservation of their language, traditions, and ancestral lands.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_KATENDE', 			'Katende' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_KATENDE_ADJ', 			'Luba' UNION ALL
SELECT 'TXT_KEY_CIV5_KATENDE_TEXT', 				'The Luba Kingdom ruled over its surrounding states with a tributary system. The mulopwe ("sacred king") was the overall leader of the empire, and maintained a large court of nobles. This court included members of the Mbudye, a secret society who preserved the oral histories of Luba. Tributary states were ruled by balopwe - "clan kings" - and paid their tributes to the central government via agricultural and mineral resources. [NEWLINE][NEWLINE]Because of its position in central Africa, Luba came to be at the center of both short-range and long-range trade routes. Luba''s trade networks allowed it to monopolize resources such as salt and copper, and to connect the northern forests of the Congo with the mineral-rich "copper belt" to its south. Longer-distance trade also allowed Luba to access the Atlantic and Indian Ocean trade networks, giving them access to luxury goods such as glass beads and cowry shells. [NEWLINE][NEWLINE]Artists were also highly esteemed in Luba. Art items - including staffs, caryatid stools, and bow stands - were important signifiers of status; accordingly, carvers were highly respected, and carried around adzes to indicate their occupation. One of the most unique types of Luba art was the lukasa memory board, a decorated piece of wood used as a mnemonic for recounting oral histories.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_LAHORE', 				'Lahore' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_LAHORE_ADJ', 				'Punjabi' UNION ALL
SELECT 'TXT_KEY_CIV5_LAHORE_TEXT', 					'Lahore, the capital of Pakistan''s Punjab province, is one of South Asia''s oldest and most culturally vibrant cities, with a history stretching back over a millennium. Often called the "Heart of Pakistan", Lahore has been a political, artistic, and intellectual hub under various empires, including the Ghaznavids, Mughals, Sikhs, and British. It flourished spectacularly during the Mughal era (16th-18th centuries), when it was adorned with grand monuments such as the Badshahi Mosque, Lahore Fort, and Shalimar Gardens-now UNESCO World Heritage Sites. Later, under Sikh ruler Maharaja Ranjit Singh and then British colonial administration, the city continued to thrive as a center of power and learning. Following Pakistan''s independence in 1947, Lahore became a symbol of national identity and resilience. Today, it remains a dynamic metropolis known for its rich heritage, lively arts, cuisine, and the warmth of its people, embodying a unique blend of history and modern energy.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_OUIDAH', 				'Ouidah' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_OUIDAH_ADJ', 				'Ouidah' UNION ALL
SELECT 'TXT_KEY_CIV5_OUIDAH_TEXT', 					'The Kingdom of Ouidah, located on the coast of present-day Benin, was a prominent West African state that rose to prominence in the 17th century. Originally a small coastal settlement, it became a significant center of trade, diplomacy, and cultural exchange due to its strategic position on the Gulf of Guinea. Ouidah was known for its role in the transatlantic slave trade, acting as a major hub where European powers, such as the Portuguese, Dutch, French, and British, established trading posts. Enslaved people from the interior were brought to Ouidah, where they were exchanged for European goods, including firearms, textiles, and alcohol. The city also became a melting pot of cultures, with European influences blending with the Vodun religious practices of the local Fon people. [NEWLINE][NEWLINE]By the 18th century, Ouidah''s prosperity attracted the attention of neighboring powers, including the Kingdom of Dahomey, which annexed Ouidah in 1727. Under Dahomean control, Ouidah continued to play a vital role in the slave trade but also faced increasing challenges, including competition with other ports and the eventual abolition of the transatlantic slave trade in the 19th century.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_PELYM', 				'Pelym' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_PELYM_ADJ', 				'Permian' UNION ALL
SELECT 'TXT_KEY_CIV5_PELYM_TEXT', 					'The Permians are a branch of the Finno-Ugric peoples and include Komis and Udmurts, speakers of Permic languages. Formerly the name Bjarmians was also used to describe these peoples. The recent research on the Finno-Ugric substrate in northern Russian dialects, however, suggests that in Bjarmaland there also lived several other Finno-Ugric groups besides the Permians. The ancestors of the Permians originally inhabited the land called Permia covering the middle and upper Kama River. Permians split into two groups, probably during the 9th century.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_POKROVKA', 			'Jaxartes' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_POKROVKA_ADJ', 			'Massagetae' UNION ALL
SELECT 'TXT_KEY_CIV5_POKROVKA_TEXT', 				'The Massagetae or Massageteans, also known as Saka tigraxauda or Orthocorybantians, were an ancient Eastern Iranian Saka people who inhabited the steppes of Central Asia and were part of the wider Scythian cultures. The Massagetae rose to power in the 8th to 7th centuries BCE, when they started a series of events with wide-reaching consequences by expelling the Scythians out of Central Asia and into the Caucasian and Pontic Steppes. The Massagetae are most famous for their queen Tomyris''s alleged defeating and killing of Cyrus, the founder of the Persian Achaemenid Empire. [NEWLINE]The Massagetae declined after the 3rd century BCE, after which they merged with some other tribes to form the Alans, a people who belonged to the larger Sarmatian tribal confederation, and who moved westwards into the Caucasian and European steppes, where they participated in the events of the Migration Period.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SARNATH', 			'Sarnath' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SARNATH_ADJ', 			'Mauryan' UNION ALL
SELECT 'TXT_KEY_CIV5_SARNATH_TEXT', 				'The Mauryan Empire, founded by Chandragupta Maurya around 321 BCE, was the first major empire to unify most of the Indian subcontinent, marking a defining moment in ancient Indian history. Centered in Pataliputra (modern-day Patna), the empire emerged after Chandragupta overthrew the Nanda Dynasty in Magadha with guidance from his advisor Chanakya (Kautilya). Under Chandragupta and his successors, especially Ashoka the Great, the Mauryan state expanded to encompass nearly all of South Asia, stretching from Afghanistan to Bengal and deep into the Deccan. The empire was known for its highly organized administration, extensive road and trade networks, and promotion of economic and cultural integration. Emperor Ashoka''s conversion to Buddhism after the bloody Kalinga War transformed the empire''s ideology, leading to the spread of Buddhism across Asia through his support of missions and inscriptions promoting moral governance (dhamma). After Ashoka''s death in 232 BCE, the empire gradually weakened due to internal divisions and regional revolts, eventually collapsing by around 185 BCE, paving the way for smaller successor kingdoms like the Shunga Dynasty.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SUCEAVA', 			'Suceava' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SUCEAVA_ADJ', 			'Moldovian' UNION ALL
SELECT 'TXT_KEY_CIV5_SUCEAVA_TEXT', 				'Suceava is a historic city in northeastern Romania, located in the region of Bukovina, near the Eastern Carpathians. Founded in the late 14th century, it served as the capital of the Principality of Moldavia from around 1388 to 1565 under rulers such as Stephen the Great, who fortified the city and built the impressive Suceava Fortress to defend against Ottoman invasions. During this period, Suceava flourished as a political, economic, and cultural center, with beautiful monasteries and churches that are now part of UNESCO''s World Heritage Sites. After the capital moved to Iași, Suceava declined in importance but remained a regional hub. It later came under Habsburg rule in the 18th century before being reunited with Romania in 1918. Today, Suceava is known for its medieval heritage, religious architecture, and as a gateway to the painted monasteries of Bukovina.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_TBILISI', 			'Tbilisi' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_TBILISI_ADJ', 			'Georgian' UNION ALL
SELECT 'TXT_KEY_CIV5_TBILISI_TEXT', 				'The nation of Georgia was first unified as a kingdom under the Bagrationi dynasty in the 9th to 10th century, arising from a number of predecessor states of ancient Colchis and Iberia. The kingdom of Georgia flourished during the 10th to 12th centuries, and fell to the Mongol invasions of Georgia and Armenia by 1243, and after a brief reunion under George V of Georgia to the Timurid Empire. By 1490, Georgia was fragmented into a number of petty kingdoms and principalities, which throughout the Early Modern period struggled to maintain their autonomy against Safavid and Ottoman domination until Georgia was finally annexed by the Russian Empire in 1801. After a brief bid for independence with the Democratic Republic of Georgia of 1918-1921, Georgia was part of the Transcaucasian Socialist Federative Soviet Republic from 1922 to 1936, and then formed the Georgian Soviet Socialist Republic until the dissolution of the Soviet Union. The current Republic of Georgia has been independent since 1991.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SANAA', 				'Sanaa' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SANAA_ADJ', 				'Yemenian' UNION ALL
SELECT 'TXT_KEY_CIV5_SANAA_TEXT', 					'In ancient times, Yemen was the home of the Sabaeans, a trading state that included parts of modern-day Ethiopia and Eritrea. Later in 275 CE, the Himyarite Kingdom was influenced by Judaism. Christianity arrived in the 4th century. Islam spread quickly in the 7th century and Yemenite troops were crucial in the early Islamic conquests. Several dynasties emerged in the 9th to 16th centuries, such as the Rasulid dynasty. The country was divided between the Ottoman and British empires in the 1800s. The Zaydi Mutawakkilite Kingdom of Yemen was established after World War I before the creation of the Yemen Arab Republic in 1962. South Yemen remained a British protectorate as the Aden Protectorate until 1967 when it became an independent state and later, a Marxist-Leninist state. The two Yemeni states united to form the modern Republic of Yemen in 1990. President Ali Abdullah Saleh was the first president of the new republic until his resignation in 2012 in the wake of the Arab Spring.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_JUYUBIT', 			'Juyubit' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_JUYUBIT_ADJ', 			'Tongva' UNION ALL
SELECT 'TXT_KEY_CIV5_JUYUBIT_TEXT', 				'The Tongva are an Indigenous people of Southern California whose ancestral lands encompass the Los Angeles Basin and the Southern Channel Islands, including Santa Catalina. Also known historically as the Gabrielino (after the Spanish Mission San Gabriel Arcángel), the Tongva lived in well-organized villages and thrived for thousands of years through fishing, hunting, and trade networks that extended across the region. Their culture was rich in spirituality, art, and environmental stewardship. The arrival of Spanish colonizers in the late 18th century brought missions, disease, and forced labor, which devastated the Tongva population and disrupted their way of life. Despite centuries of displacement and marginalization under Spanish, Mexican, and American rule, the Tongva people have preserved their identity and continue to advocate for recognition, cultural revitalization, and stewardship of their ancestral lands within the modern Los Angeles area.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ANANGULA', 			'Anangula' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ANANGULA_ADJ', 			'Aleutic' UNION ALL
SELECT 'TXT_KEY_CIV5_ANANGULA_TEXT', 				'The Aleut people, also known as the Unangax̂, are indigenous to the Aleutian Islands, Pribilof Islands, and parts of the Alaskan Peninsula in the North Pacific. For thousands of years, they thrived in the challenging Arctic environment, developing a maritime culture centered on hunting sea mammals like seals, sea lions, and whales, as well as fishing and gathering. They are renowned for their expertly crafted tools, kayaks (baidarkas), and waterproof clothing made from animal skins. Aleut communities were organized into kin-based societies, and their spiritual beliefs were deeply intertwined with nature and the sea, reflected in their oral traditions, rituals, and shamanistic practices. [NEWLINE][NEWLINE]Contact with Russian explorers in the 18th century marked a significant turning point in Aleut history. Russian colonizers exploited the Aleuts for their expertise in hunting sea otters, driving them into forced labor and significantly disrupting their traditional way of life. Over time, diseases introduced by Europeans further decimated the population. The Aleuts'' plight continued under U.S. control after Alaska was purchased in 1867, with displacement and cultural suppression persisting into the 20th century. Despite these challenges, the Aleuts have preserved their cultural identity, reviving traditional practices, crafts, and language in recent decades. Today, they are recognized as one of Alaska''s Native groups, with efforts underway to sustain their heritage and advocate for their rights.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_LONGYAN', 			'Longyan' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_LONGYAN_ADJ', 			'Hakkan' UNION ALL
SELECT 'TXT_KEY_CIV5_LONGYAN_TEXT', 				'The Hakka people are a Han Chinese subgroup with a unique cultural identity and history marked by migration and resilience. Their origins are believed to trace back to northern China, from where they began migrating southward as early as the Jin dynasty (4th century CE), driven by war, famine, and social upheaval. Over centuries, the Hakka settled in southern provinces like Guangdong, Fujian, and Jiangxi, often inhabiting less fertile lands and mountainous areas. Their name, "Hakka," meaning "guest families," reflects their history of displacement and integration into new communities. The Hakka developed distinct customs, language, and architectural styles, including the iconic tulou-fortified earth dwellings that provided communal living and defense. [NEWLINE][NEWLINE]Throughout history, the Hakka played a significant role in shaping China''s political and social landscape. Many Hakka leaders, including Sun Yat-sen, the father of modern China, and Hong Xiuquan, leader of the Taiping Rebellion, emerged during periods of reform and upheaval. Their reputation for perseverance and adaptability extended beyond China as Hakka emigrants established communities worldwide, particularly in Southeast Asia, the Americas, and Africa, during the 19th and 20th centuries. Today, the Hakka maintain a strong cultural identity, celebrated for their contributions to Chinese history, cuisine, and diaspora, while continuing to balance tradition with modernity in a globalized world.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_AYUTTHAYA', 			'Ayutthaya' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_AYUTTHAYA_ADJ', 			'Ayutthaya' UNION ALL
SELECT 'TXT_KEY_CIV5_AYUTTHAYA_TEXT', 				'Ayutthaya was a powerful and prosperous kingdom in central Thailand, founded in 1350 by King Ramathibodi I on an island at the confluence of three rivers. Strategically located between China, India, and the Malay Archipelago, it became a thriving center of trade, diplomacy, and culture, attracting merchants from Europe, Japan, Persia, and beyond. At its height, Ayutthaya was renowned for its grand temples, palaces, and cosmopolitan society, serving as the capital of Siam for over four centuries. The kingdom developed a distinct Thai identity, blending influences from neighboring civilizations while maintaining political dominance in the region. However, in 1767, Ayutthaya was destroyed by Burmese forces, leading to its collapse and the loss of much of its cultural heritage. The ruins of the old city, now a UNESCO World Heritage Site, stand as a testament to Ayutthaya''s former grandeur and its central role in Thai history.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_PALMYRA', 			'Palmyra' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_PALMYRA_ADJ', 			'Palmyrene' UNION ALL
SELECT 'TXT_KEY_CIV5_PALMYRA_TEXT', 				'Palmyra, also called Tadmur, Tadmor, or Tudmur, is an ancient city in south-central Syria, 210 km northeast of Damascus. The name Palmyra, meaning "city of palm trees," was conferred upon the city by its Roman rulers in the 1st century AD; Tadmur, Tadmor, or Tudmur, the pre-Semitic name of the site, is also still in use. The city is mentioned in tablets dating from as early as the 19th century BC. It attained prominence in the 3rd century bce, when a road through it became one of the main routes of east-west trade. Palmyra was built on an oasis lying approximately halfway between the Mediterranean Sea (west) and the Euphrates River (east), and it helped connect the Roman world with Mesopotamia and the East.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_AL_TIRABIN', 			'Al-Tirabin' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_AL_TIRABIN_ADJ', 			'Bedouin' UNION ALL
SELECT 'TXT_KEY_CIV5_AL_TIRABIN_TEXT', 				'The Bedouins are traditionally nomadic Arab tribes known for their deep-rooted culture, pastoral lifestyle, and strong sense of tribal identity, originating from the deserts of the Arabian Peninsula and spreading across North Africa, the Levant, and parts of the Middle East. Historically, they lived by herding camels, goats, and sheep, moving seasonally in search of water and grazing lands, and became skilled in desert survival, oral poetry, and hospitality. Their social structure was built around kinship, honor, and loyalty to the tribe, with leaders known as sheikhs. Over time, as modern states expanded and urbanization increased in the 20th century, many Bedouins settled in towns or adopted semi-nomadic lives, though elements of their traditions, such as dress, poetry, and music-remain vital symbols of Arab cultural heritage and identity.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_HANUABADA', 			'Hanuabada' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_HANUABADA_ADJ', 			'Motu' UNION ALL
SELECT 'TXT_KEY_CIV5_HANUABADA_TEXT', 				'The Motu are people from southeastern Papua New Guinea and were the original people of the land of Port Moresby, the capital and largest city in the country. The largest Motu settlement and traditional centre of the group is the town of Hanuabada, not too far up the coast from Port Moresby. Today it is almost part of Port Moresby itself as it is only a few kilometres northwest. The name Hanuabada comes from the Motu language and simply means "big village". Their language is an Austronesian language, but some today, speak an English based pidgin called Tok Pisin. The Motu lived on the stretch of coastline first settled permanently by Europeans on the island and are thus, more well-chronicled than others. They also have a tradition of sailing, using multihulled rafts with crab-claw shaped sails made from coconut fibre to trade with others near them. The Motu inhabited mostly along the bridge, not moving far inland as they were traders and fishermen.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_BALKH', 				'Bactra' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_BALKH_ADJ', 				'Bactrian' UNION ALL
SELECT 'TXT_KEY_CIV5_BALKH_TEXT', 					'Bactra, known today as Balkh in northern Afghanistan, is one of the oldest cities in the world and was a major center of ancient civilization in Central Asia. Situated along the Silk Road, it served as the capital of the ancient region of Bactria and flourished as a hub of trade, culture, and religion. Believed to have been founded before 2000 BCE, Bactra was successively ruled by the Achaemenid Persians, conquered by Alexander the Great in the 4th century BCE, and later became the heart of the Greco-Bactrian Kingdom. It was also a key center of Zoroastrianism and, later, Buddhism, with numerous monasteries and stupas that influenced spiritual life across Asia. Despite repeated invasions from the Kushans to the Arabs and Mongols, Bactra retained its reputation as the "Mother of Cities", symbolizing the enduring legacy of ancient Iranian and Central Asian civilization.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_TONDO', 				'Tondo' UNION ALL -- replaces Donostia (Irunea)
SELECT 'TXT_KEY_CITYSTATE_TONDO_ADJ', 				'Tagalog' UNION ALL
SELECT 'TXT_KEY_CIV5_TONDO_TEXT', 					'Aptly named "the people of the river", the hardy and adaptable Tagalogs are the second largest ethnolingustic group in the Philippines, primarily inhabiting the central part of Luzon, including Manila and nearby provinces. Their history dates back to pre-colonial times when they established organized societies along rivers and coastlines, relying on agriculture, fishing, and trade. Tagalog communities were governed by datus (chieftains) and were part of larger polities called barangays. They engaged in trade with neighboring Asian regions, including China, India, and the Malay Archipelago, introducing elements of Hindu-Buddhist and Islamic culture into their society. The Tagalog language evolved as a significant medium for communication, with a rich oral tradition of epics, songs, and proverbs that reflected their worldview. [NEWLINE][NEWLINE]With the arrival of Spanish colonizers in the 16th century, the Tagalogs were among the first groups to encounter Western influence. The Spaniards introduced Christianity, which became deeply ingrained in Tagalog culture, along with colonial governance and economic systems. The Tagalog region became a center of resistance against colonial rule, producing revolutionary leaders such as Andrés Bonifacio and Apolinario Mabini during the Philippine Revolution. In modern times, the Tagalogs have played a central role in shaping Philippine identity, as their language serves as the basis for Filipino, the national language.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_JETARKTE', 			'Jetarkte' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_JETARKTE_ADJ', 			'Kaweskar' UNION ALL
SELECT 'TXT_KEY_CIV5_JETARKTE_TEXT', 				'The history of the Kaweskar people is a story of a fruitless struggle of a people dearly trying to keep their traditions alive in an uncaring world that just seems to haphazardly lend them a hand at the best of times. A people who were witnessed at the very early days of American exploration yet weren''t fully contacted until well entered the 20th century. People living in one of the harshest environments the world could offer while seeing the world move around them, not relevant to establish permanent trade with, yet not possessing enough wealth to seek out to fight them either. A world ravaged by plague which decimated their population, directing them onto a path of annihilation that made them lose their very faith on the spirits of the Earth. Yet people who still managed to overcome, to survive, and to live to this day. The very earlier contacts with the Kaweskar were done during the days of Magellan and the early explorers of the new world, yet this territory wasn''t truly colonized by the white man until the 20th century, a time when their population was already decimated due to the overhunting of their traditional food sources and the illnesses they had no immunity to that had made their presence on this land.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MBABANE', 			'Mbabane' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MBABANE_ADJ', 			'Eswatinian' UNION ALL
SELECT 'TXT_KEY_CIV5_MBABANE_TEXT', 				'Mbabane, the capital and largest city of Eswatini (formerly Swaziland), is located in the country''s northwestern highlands along the Mbabane River, surrounded by the scenic Dlangeni and Mdzimba Mountains. Established as a colonial administrative center by the British in the early 1900s, it became the capital of the British protectorate of Swaziland in 1902 and later retained its status after the nation gained independence in 1968. Named after Chief Mbabane Kunene, the area''s early inhabitant, the city grew around its government institutions and trade routes, developing into the political and commercial heart of the country. Today, Mbabane blends modern urban life with traditional Swazi culture and serves as a gateway to Eswatini''s mountain landscapes, making it both an administrative hub and a center of cultural and economic activity.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_TUNIS', 				'Tunis' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_TUNIS_ADJ', 				'Tunisian' UNION ALL
SELECT 'TXT_KEY_CIV5_TUNIS_TEXT', 					'Tunis, the capital and largest city of Tunisia, lies on the Mediterranean coast near the ancient ruins of Carthage and serves as the political, economic, and cultural heart of the country. Its history stretches back to at least the 9th century BCE, when it began as a Berber settlement later influenced by Phoenician Carthage, Roman rule, and Islamic conquest in the 7th century CE. Under the Aghlabids and later the Hafsids, Tunis rose to prominence as a major center of learning, trade, and Islamic culture in North Africa. The city flourished further under Ottoman and then French colonial rule, blending Arab, Mediterranean, and European influences in its architecture and society. Following Tunisia''s independence in 1956, Tunis became the seat of government and a symbol of national identity. Today, its bustling medina, recognized as a UNESCO World Heritage Site, stands as a living testament to over two millennia of history and cultural exchange.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MENDYARRUP', 			'Mendyarrup' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MENDYARRUP_ADJ', 			'Noongar' UNION ALL
SELECT 'TXT_KEY_CIV5_MENDYARRUP_TEXT', 				'The Noongar are the Aboriginal people of the southwest region of Western Australia, whose ancestral lands stretch from Jurien Bay in the north to Esperance in the southeast, encompassing the area around Perth. With a history spanning over 45,000 years, the Noongar have maintained a deep spiritual and cultural connection to boodja (land), guided by the Dreaming stories that explain the creation of their environment and laws. Traditionally, Noongar society consisted of interconnected groups with their own territories, languages, and customs, relying on seasonal movement, hunting, and gathering for sustenance. Following British colonization in 1829, the Noongar faced displacement, loss of land, and suppression of culture, yet they have continued to preserve and revive their language, traditions, and identity. Today, the Noongar people play a vital role in cultural education, environmental stewardship, and reconciliation efforts across Western Australia, embodying one of the oldest continuous living cultures on Earth.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SADDARVAZEH', 		'Saddarvazeh' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SADDARVAZEH_ADJ', 		'Parthian' UNION ALL
SELECT 'TXT_KEY_CIV5_SADDARVAZEH_TEXT', 			'Saddarvazeh or Hecatompylos, meaning "City of a Hundred Gates" in Persian and Greek, respectively, was an ancient city located in northeastern Iran, near modern-day Damghan or Shahrud. It served as the capital of the Parthian Empire under the Arsacid dynasty around the 3rd century BCE, becoming a major political and commercial hub on the Silk Road connecting Mesopotamia with Central Asia. Originally a Seleucid foundation or an older Hellenistic settlement rebuilt by the Parthians, Hecatompylos thrived as a royal residence and strategic stronghold until it was later eclipsed by other Parthian capitals such as Ctesiphon. Although little remains of the city today, its ruins mostly identified at the site of Sahr-e Qumis, ancient writers like Strabo and Pliny the Elder praised its grandeur and its position as a gateway between East and West.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_BAGHCASARAY', 		'Baghcasaray' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_BAGHCASARAY_ADJ', 		'Crimean' UNION ALL
SELECT 'TXT_KEY_CIV5_BAGHCASARAY_TEXT', 			'Bakhchisaray (also spelled Baghchasaray or Bakhchysarai) is a historic town in Crimea, Ukraine, known as the former capital of the Crimean Khanate from the 16th to the 18th century. Founded around 1532 by Sahib I Giray, it became the political, cultural, and spiritual center of the Crimean Tatars. The town''s name, derived from Persian (baghche-saray meaning "garden palace"), reflects its picturesque setting among gardens and mountain valleys. Its most famous landmark, the Bakhchisaray Palace (Hansaray), served as the residence of the Crimean khans and is celebrated for its Islamic architecture, intricate tilework, and the "Fountain of Tears", immortalized by Alexander Pushkin in his 1823 poem. Though the city declined after the Russian annexation of Crimea in 1783, it remains a symbol of Crimean Tatar heritage and resilience.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_CAVVANBAH', 			'Cavvanbah' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_CAVVANBAH_ADJ', 			'Bundjalung' UNION ALL
SELECT 'TXT_KEY_CIV5_CAVVANBAH_TEXT', 				'The Bundjalung (also spelled Bungjalung) are an Aboriginal Australian people whose traditional lands span the northern coast and hinterlands of New South Wales and southeastern Queensland, encompassing areas around Byron Bay, Lismore, and the Clarence and Richmond Rivers. With a history extending tens of thousands of years, the Bundjalung developed a rich cultural life centered on their deep connection to Country (ngalingah jugun), expressed through language, songlines, and ceremonial practices tied to the land and waterways. Traditionally, they lived as skilled hunters, fishers, and gatherers, with complex kinship systems and spiritual beliefs grounded in the Dreaming. Following European colonization in the 19th century, the Bundjalung experienced dispossession, violence, and disruption of cultural traditions, yet they have continued to maintain and revive their language and heritage. Today, Bundjalung people play a vital role in cultural preservation, land management, and advocacy for Indigenous rights, ensuring the survival and renewal of one of Australia''s oldest living cultures.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_BOGANIDA', 			'Boganida' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_BOGANIDA_ADJ', 			'Dolgan' UNION ALL
SELECT 'TXT_KEY_CIV5_BOGANIDA_TEXT', 				'The Dolgans are a Turkic-speaking Indigenous people of northern Siberia, primarily inhabiting the Taymyr Peninsula in Russia''s Krasnoyarsk Krai. Their origins trace to the 17th and 18th centuries, when groups of Evenks, Yakuts, and Russian settlers intermingled in the Arctic regions, forming a distinct cultural and linguistic identity. Traditionally, the Dolgans were semi-nomadic reindeer herders, hunters, and fishers, adapting to the harsh tundra environment and developing a lifestyle deeply tied to the seasonal rhythms of the Arctic. They speak the Dolgan language, closely related to Yakut (Sakha), and maintain rich oral traditions, folklore, and shamanic practices, although many also practice Russian Orthodoxy. During the Soviet period, collectivization and sedentarization transformed Dolgan society, concentrating communities into villages and disrupting traditional livelihoods. Despite these pressures, the Dolgans have preserved much of their cultural heritage and continue to play a central role in the cultural and ecological fabric of the Russian Arctic.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SIPIWININIWAK', 		'Sipiwininiwak' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SIPIWININIWAK_ADJ', 		'Cree' UNION ALL
SELECT 'TXT_KEY_CIV5_SIPIWININIWAK_TEXT', 			'The Cree are one of the largest Indigenous groups in North America, whose traditional territories span vast regions of Canada, from the subarctic forests of Alberta and Saskatchewan to the shores of James and Hudson Bays in Quebec and Ontario, with related communities also in the northern United States. Believed to have originated near the Hudson Bay area, the Cree expanded westward over centuries, adapting to diverse environments as both forest dwellers (Nehiyawak) and Plains hunters (Paskwawiyiniwak). Their culture and language, part of the Algonquian family, are deeply connected to the land, emphasizing respect for nature, oral storytelling, and community kinship. The Cree were key participants in the fur trade from the 17th century onward, forging extensive relationships with European traders while maintaining their own political and spiritual systems. Despite the impacts of colonization, treaties, and residential schools, the Cree continue to sustain vibrant communities and play a leading role in Indigenous governance, cultural revitalization, and environmental stewardship across Canada today.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ATOLAN', 				'A''tolan' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ATOLAN_ADJ', 				'Amis' UNION ALL
SELECT 'TXT_KEY_CIV5_ATOLAN_TEXT', 					'The Amis, also known as Pangcah, are the largest Indigenous group in Taiwan, traditionally inhabiting the island''s eastern coastal plains and river valleys from Hualien to Taitung. With a history stretching back thousands of years, the Amis are part of the Austronesian cultural and linguistic family, sharing deep ancestral ties with other Pacific Island peoples. Traditionally, they lived in matrilineal societies organized around extended families and age-grade systems, with men''s and women''s roles clearly defined through communal rituals and agricultural practices such as rice and millet farming. Their rich oral traditions, music, and dance, especially the ilisin harvest festival, reflect their close relationship with nature and the spiritual world. During the Japanese colonial period (1895-1945) and later under Chinese rule, the Amis faced assimilation pressures, yet they have preserved much of their language and customs. Today, the Amis are at the forefront of Taiwan''s Indigenous cultural revival, advocating for land rights, education, and the recognition of their heritage within the broader national identity.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ISHIYAMA', 			'Ishiyama' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ISHIYAMA_ADJ', 			'Ikko-ikki' UNION ALL
SELECT 'TXT_KEY_CIV5_ISHIYAMA_TEXT', 				'The Ikko-ikki were militant groups of Buddhist monks, peasants, and local warriors in 15th-16th century Japan who rose up against feudal lords and samurai rule. Centered around the teachings of the Jodo Shinshu (True Pure Land) sect of Buddhism, they were united by religious devotion and a desire for social equality. Emerging during the chaotic Sengoku period, these leagues established autonomous communities in several provinces, most notably controlling Ishiyama Hongan-ji fortress temple near Osaka. Their strong resistance challenged powerful warlords, including Oda Nobunaga, who eventually crushed the movement in the late 16th century. Though defeated, the Ikko-ikki left a lasting legacy as one of the earliest large-scale, grassroots movements in Japanese history, blending faith with political resistance.';

INSERT INTO Language_en_US (Tag, Text)
SELECT 'TXT_KEY_CITYSTATE_YAIUWA', 				'Yaiuwa' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_YAIUWA_ADJ', 				'Manek''enk' UNION ALL
SELECT 'TXT_KEY_CIV5_YAIUWA_TEXT', 					'The Haush, also known as the Manek''enk, were an Indigenous people who inhabited the southeastern part of Tierra del Fuego, the large island at the southern tip of South America shared by modern-day Chile and Argentina. Closely related to the Selk''nam (Ona) people, the Haush lived primarily by hunting sea lions, guanacos, and birds, as well as gathering shellfish and wild plants, adapting skillfully to the harsh subpolar environment. Their society was organized into small nomadic groups with a rich spiritual and ritual life tied to nature. The arrival of European explorers and settlers in the 19th century, followed by sheep ranching and gold prospecting, brought devastating diseases, violence, and displacement that led to the near extinction of the Haush by the early 20th century. Today, they are remembered as one of the southernmost peoples of the world, whose way of life reflected extraordinary resilience in one of Earth''s most challenging environments.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SHAHRAZUR', 			'Shahrazur' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_SHAHRAZUR_ADJ', 			'Gorani' UNION ALL
SELECT 'TXT_KEY_CIV5_SHAHRAZUR_TEXT', 				'Shahrizor or Shahrazur is a region part of Kurdistan Region, Iraq situated in the Sulaymaniyah Governorate and west of Avroman. Shahrizor is a fertile plain watered by the tributaries of Tandjaro river which flows to Diyala and Tigris rivers. Extensive archaeological research, especially since 2009, at sites like Bakr Awa, Tell Begum, Gird-î Qalrakh, and Bestansur (which is on the UNESCO World Heritage Tentative List), has shown that the plain has been continuously occupied since prehistoric times. [NEWLINE]Sharazur was incorporated into Ardalan Principality from 11th century until the 16th and was its first capital. Ardalan was a hereditary Kurdish vassaldom in western Iran from around the 14th century until 1865 or 1868 with Sanandaj as capital. The territory corresponded roughly to present-day Kurdistan Province of Iran and the rulers were loyal to the Qajar Empire. Baban was its main rival. Gorani was the literary language and lingua franca. When the vassaldom fell, literary work in Gorani ceased.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_CARARIES', 			'Cararíes' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_CARARIES_ADJ', 			'Omagua' UNION ALL
SELECT 'TXT_KEY_CIV5_CARARIES_TEXT', 				'The Omagua people (also known as the Cambeba) were speakers of a Tupian language who lived along the upper Amazon, in modern-day Brazil and Peru. Their most significant sites were largely along the Solimões River, as well as various other rivers in the region. One of the Omagua''s most distinctive cultural traits was the practice of forehead-flattening; a piece of wood would be bound to the foreheads of Omagua babies and left there, causing the forehead to grow into a flat shape. The Omagua took great pride in this practice, and considered most neighboring groups uncivilized for not doing so. What was most immediately distinctive to outside observers, however, was the clothing woven by the Omagua; whereas many Amazonian tribes wore little to no clothing, the Omagua dressed in multicolored cotton textiles, a trait that drew approving comments from the leaders of several Spanish expeditions.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_KITCISIPIRINIK', 		'Kitcisìpirinik' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_KITCISIPIRINIK_ADJ', 		'Algonquin' UNION ALL
SELECT 'TXT_KEY_CIV5_KITCISIPIRINIK_TEXT', 			'The Algonquin are an Indigenous people of North America traditionally inhabiting the Ottawa River valley and surrounding regions in what is now Quebec and Ontario, Canada. They are part of the larger Algonquian language family, which includes many tribes across northeastern North America. Historically, the Algonquin lived in semi-nomadic bands, relying on hunting, fishing, and gathering, and they maintained extensive trade networks with neighboring First Nations. They played a key role in the early fur trade with French explorers and settlers in the 17th century, forming important alliances that shaped regional history. However, European colonization brought significant disruptions, including disease, displacement, and loss of land. Despite these challenges, the Algonquin people have preserved much of their cultural heritage, language, and traditions, and today continue to advocate for their rights, land claims, and cultural revitalization within Canada.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_KOKAND', 				'Kokand' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_KOKAND_ADJ', 				'Kokand' UNION ALL
SELECT 'TXT_KEY_CIV5_KOKAND_TEXT', 					'The town of Kokand is one of the oldest towns in Uzbekistan and is situated in the western part of Fergana Valley. In the chronicles of the 10th century, the first written documents concerning town of Hukande, Havokande (old names of the town). In the 13th century, like most of Central Asian towns, the Mongols ruined the city. The town is a significant hub for trading on the Silk Route. [NEWLINE]Kokand has existed since at least the 10th century, under the name of Khavakand, and was frequently mentioned in traveler''s accounts of the caravan route between South Asia and East Asia. The Han Dynasty of China conquered the entire city in the 1st Century B.C. Later, the Arabs conquered the region from Tang Empire. The Mongols destroyed Kokand in the 13th century. [NEWLINE]The present city began as a fort in 1732 on the site of another older fortress called Eski-Kurgan. In 1740, it became the capital of an Uzbek kingdom, the Khanate of Kokand, which reached as far as Kyzylorda to the west and Bishkek to the northeast. Kokand was also the major religious center of the Fergana Valley, boasting more than 300 mosques. [NEWLINE]The Khanate of Kokand was established in 1709 when the Shaybanid emir Shahrukh, of the Ming Tribe of Uzbeks, declared independence from the Khanate of Bukhara, establishing a state in the eastern part of the Fergana Valley. He built a citadel as his capital in the small town of Kokand, thus starting the Khanate of Kokand. His son, Abdul Kahrim Bey, and grandson, Narbuta Bey, enlarged the citadel, but both were forced to submit as a protectorate, and pay tribute to, the Qing dynasty between 1774 and 1798.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MUTAWAYNATJI', 		'Mutawaynatji' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_MUTAWAYNATJI_ADJ', 		'Palawa' UNION ALL
SELECT 'TXT_KEY_CIV5_MUTAWAYNATJI_TEXT', 			'The Palawa are the Aboriginal people of the Australian island of Tasmania, located south of the mainland. For much of the 20th century, the Tasmanian Aboriginal people were widely, and erroneously, thought of as being an extinct cultural and ethnic group that had been intentionally exterminated by white settlers. Contemporary figures (2016) for the number of people of Tasmanian Aboriginal descent vary according to the criteria used to determine this identity, ranging from 6,000 to over 23,000.[NEWLINE][NEWLINE]First arriving in Tasmania (then a peninsula of Australia) around 40,000 years ago, the ancestors of the Aboriginal Tasmanians were cut off from the Australian mainland by rising sea levels c. 6000 BC. They were entirely isolated from the outside world for 8,000 years until European contact.[NEWLINE][NEWLINE]Before British colonisation of Tasmania in 1803, there were an estimated 3,000-15,000 Palawa. The Palawa population suffered a drastic drop in numbers within three decades, so that by 1835 only some 400 full-blooded Tasmanian Aboriginal people survived, most of this remnant being incarcerated in camps where all but 47 died within the following 12 years. No consensus exists as to the cause, over which a major controversy arose. The traditional view held that this dramatic demographic collapse was the result of the impact of introduced diseases, rather than the consequence of policy. Others, like Henry Reynolds, attribute the decline moreso to losses in the Black War. Many historians of colonialism and genocide, such as Ben Kiernan, Colin Tatz, and Benjamin Madley, consider that the Tasmanian decimation qualifies as genocide by the definition of Raphael Lemkin adopted in the UN Genocide Convention. The complete Aboriginal Tasmanian languages have been lost; research suggests that the languages spoken on the island belonged to several distinct language families. Some original Tasmanian language words remained in use with Palawa people in the Furneaux Islands, and there are some efforts to reconstruct a language, called Palawa kani, from the available wordlists.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_NGAZARGAMU', 			'Ngazargamu' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_NGAZARGAMU_ADJ', 			'Bornu' UNION ALL
SELECT 'TXT_KEY_CIV5_NGAZARGAMU_TEXT', 				'The Kanem-Bornu Empire was an empire that existed in what is now modern day Chad and Nigeria. It was known to Arab geographers as the Kanem Empire from the 9th century AD onwards and lasted as the independent kingdom of Bornu until 1900. The history of the empire is mainly known from the Royal Chronicle or Girgam discovered in 1851 by the German traveler Heinrich Barth. At its height, the Kanem-Bornu Empire encompassed an area covering not only much of Chad, but also parts of modern southern Libya, eastern Niger, northeastern Nigeria and northern Cameroon. It was located at the southern end of the trans-Saharan trade route between Tripoli and the region of Lake Chad. It is a hot, arid region with several oases, the largest being Lake Chad.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SHAMAKHI', 			'Shamakhi' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_SHAMAKHI_ADJ', 			'Shirvani' UNION ALL
SELECT 'TXT_KEY_CIV5_SHAMAKHI_TEXT', 				'Shirvan is a historical region in the eastern Caucasus, as known in both pre-Islamic Sasanian and Islamic times. Maintaining independence or vassalage for 800 years between 809 and 1607, Shirvan was a center of Islamic culture and trade. Today, the region is an industrially and agriculturally developed part of the Republic of Azerbaijan that stretches between the western shores of the Caspian Sea and the Kura River, centered on the Shirvan Plain.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_THABA_BOSIU', 		'Thaba Bosiu' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_THABA_BOSIU_ADJ', 		'Basotho' UNION ALL
SELECT 'TXT_KEY_CIV5_THABA_BOSIU_TEXT', 			'The territory now known as Lesotho was occupied as early as the Neolithic Period (New Stone Age) by Khoisan-speaking hunter-gatherers. From about the 16th century, African farmers-the ancestors of the present population-moved across the grasslands of Southern Africa and settled in the fertile valleys of the Caledon River, where they came to dominate the hunters of the region. These stock-keeping agriculturalists belonged to the large Sotho group and were divided into numerous clans that formed the nucleus of chiefdoms, whose members occupied villages.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_VADUZ', 				'Vaduz' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_VADUZ_ADJ', 				'Liechtenstein' UNION ALL
SELECT 'TXT_KEY_CIV5_VADUZ_TEXT', 					'Vaduz is the capital of Liechtenstein, nestled along the Rhine River at the foot of the Alps. Though small in size, it holds great historical and political significance. The area was first settled in the medieval period, and Vaduz was officially founded in the 14th century. It became the administrative center after the purchase of the county by the Liechtenstein family in 1712, eventually giving its name to the entire principality. Over time, Vaduz grew from a modest village into a political and cultural hub, particularly after Liechtenstein gained full sovereignty in 1866. Dominating the town is Vaduz Castle, the residence of the princely family. Today, Vaduz is known for its blend of historic charm and modern institutions, including museums, government buildings, and financial centers, while remaining one of Europe''s most picturesque capitals.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_VICTORIA', 			'Victoria' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_VICTORIA_ADJ', 			'Seychellois' UNION ALL
SELECT 'TXT_KEY_CIV5_VICTORIA_TEXT', 				'Seychelles, officially the Republic of Seychelles, is an archipelagic island country in the Indian Ocean at the eastern edge of the Somali Sea. It consists of 115 islands. Its capital and largest city, Victoria, lies 1,500 kilometres east of mainland Africa. Other nearby island countries and territories include Comoros, Mayotte (territory of France), Madagascar, Réunion (territory of France), and Mauritius to the south; as well as the Maldives and Chagos Archipelago to the east. With a population of roughly 94,367, it has the smallest population of any sovereign African country. [NEWLINE][NEWLINE]Seychelles was uninhabited prior to being encountered by Europeans in the 16th century. It faced competing French and British interests until coming under full British control in the late 19th century. Since proclaiming independence from the United Kingdom in 1976, Seychelles has developed from a largely agricultural society to a market-based diversified economy, characterized by rapidly rising service, public sector, and tourism activities. From 1976 until 2015, nominal GDP grew nearly sevenfold, and purchasing power parity increased nearly sixteenfold. Since the late 2010s, the government has taken steps to encourage foreign investment.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ASMARA', 				'Asmara' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_ASMARA_ADJ', 				'Eritrean' UNION ALL
SELECT 'TXT_KEY_CIV5_ASMARA_TEXT', 					'Eritrea, country of the Horn of Africa, located on the Red Sea. Eritrea''s coastal location has long been important in its history and culture-a fact reflected in its name, which is an Italianized version of Mare Erythraeum, Latin for "Red Sea." The Red Sea was the route by which Christianity and Islam reached the area, and it was an important trade route that such powers as Turkey, Egypt, and Italy hoped to dominate by seizing control of ports on the Eritrean coast. Those ports promised access to the gold, coffee, and slaves sold by traders in the Ethiopian highlands to the south, and, in the second half of the 20th century, Ethiopia became the power from which the Eritrean people had to free themselves in order to create their own state.[NEWLINE][NEWLINE]In 1993, after a war of independence that lasted nearly three decades, Eritrea became a sovereign country. During the long struggle, the people of Eritrea managed to forge a common national consciousness, but, with peace established, they faced the task of overcoming their ethnic and religious differences in order to raise the country from a poverty made worse by years of drought, neglect, and war. Eritrea''s capital and largest city is Asmara (Asmera).' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_TORSHAVN', 			'Tórshavn' UNION ALL  -- replaces Balley Chashtal
SELECT 'TXT_KEY_CITYSTATE_TORSHAVN_ADJ', 			'Faroese' UNION ALL
SELECT 'TXT_KEY_CIV5_TORSHAVN_TEXT', 				'The Faroe Islands, called Føroyar in the native Faroese language, is a self-governing country within the Kingdom of Denmark. It consists of an archipelago in the northern Atlantic Ocean, north of Scotland and approximately halfway between Norway and Iceland. The current population of the islands is about 50,000, nearly all of whom are descendants of Norse-Gaels who settled the archipelago in about 650 AD. Despite being fairly isolated, the Faroe Islands are highly modernized, and are ranked in the highest possible category of the Human Development Index. Although a part of the Kingdom of Denmark, the Faroe Islands have exercised home rule since 1948.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_CARAL', 				'Caral' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_CARAL_ADJ', 				'Caral' UNION ALL
SELECT 'TXT_KEY_CIV5_CARAL_TEXT', 					'The Norte Chico culture, more formally referred to as the Caral-Supe Civilization, was a pre-Columbian culture that developed on the north-central coast of what is today Peru. It has been established as the oldest known civilization in the Americas, flourishing between 3200-1800 BC, and one of the six sites where civilization independently originated in the ancient world. Norte Chico potentially represents a unique reliance on maritime food sources in absence of a staple cereal; however, current studies also stress the role of agriculture in supporting industry and augmenting diet. It is likely that Norte Chico was the cultural predecessor for many of the great subsequent Andean civilizations, such as the Chavin and Inca.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DAKAR', 				'Dakar' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_DAKAR_ADJ', 				'Senegalese' UNION ALL
SELECT 'TXT_KEY_CIV5_DAKAR_TEXT', 					'The Republic of Senegal is a country in West Africa. Senegal is bordered by Mauritania in the north, Mali to the east, Guinea to the southeast, and Guinea-Bissau to the southwest. Senegal also borders The Gambia, a country occupying a narrow sliver of land along the banks of the Gambia River, which separates Senegal''s southern region of Casamance from the rest of the country. Senegal also shares a maritime border with Cape Verde. Senegal''s economic and political capital is Dakar. [NEWLINE][NEWLINE]The unitary presidential republic is the westernmost country in the mainland of the Old World, or Afro-Eurasia, and owes its name to the Senegal River, which borders it to the east and north. Senegal covers a land area of almost 197,000 square kilometres (76,000 sq mi) and has an estimated population of about 15 million. The climate is typically Sahelian, though there is a rainy season.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_KAGYRGYN', 			'Kagyrgyn' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_KAGYRGYN_ADJ', 			'Chukchi' UNION ALL
SELECT 'TXT_KEY_CIV5_KAGYRGYN_TEXT', 				'The Chukchi are an Indigenous people native to the Chukotka Peninsula in the far northeastern part of Siberia, Russia. Traditionally, they are divided into two main groups: the "maritime Chukchi", who lived along the Arctic coast and relied on hunting whales, walruses, and seals, and the "reindeer Chukchi", who herded reindeer inland. Their culture is deeply rooted in animism, shamanism, and a close relationship with the natural environment. First recorded contact with Russians occurred in the 17th century, leading to conflicts and eventual integration under the Russian Empire. Despite Soviet-era pressures to assimilate, the Chukchi preserved much of their language, traditions, and nomadic way of life. Today, many still live in their ancestral lands, maintaining cultural practices while also participating in modern Russian society.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_KARIATEBIKE', 		'Kariatebike' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_KARIATEBIKE_ADJ', 		'Kiribati' UNION ALL
SELECT 'TXT_KEY_CIV5_KARIATEBIKE_TEXT', 			'Kiribati is an island nation located in the central Pacific Ocean. Its history is intertwined with the migration of Polynesian peoples and European colonialism. [NEWLINE]The earliest known inhabitants of Kiribati were Polynesians who likely settled in the region around 2,000 BCE. These seafaring people developed a unique culture, which included fishing, farming, and social systems centered around clan and island communities. [NEWLINE]European contact with Kiribati began in the late 18th century when British and French explorers arrived in the region. The islands became part of the British Empire in the late 19th century and were incorporated into the Gilbert and Ellice Islands Colony. [NEWLINE]During World War II, Kiribati was occupied by Japanese forces, who built military installations on some of the islands. After the war, the islands returned to British control. [NEWLINE]In the 1960s, political changes occurred in Kiribati as the desire for self-governance grew. The Gilbert Islands gained independence from Britain in 1979 and became the Republic of Kiribati. The Ellice Islands, present-day Tuvalu, separated from Kiribati and became an independent nation in 1978. [NEWLINE]Since gaining independence, Kiribati has faced numerous challenges, including population growth, limited resources, and the impact of climate change. The country consists of 33 coral atolls and islands, most of which are very low-lying and vulnerable to rising sea levels. Kiribati has been at the forefront of international discussions on climate change and has sought solutions to protect its people and preserve its land. [NEWLINE]The economy of Kiribati relies heavily on subsistence farming, fishing, and international aid. The government has also explored revenue sources through tourism and the sale of fishing licenses to foreign countries. [NEWLINE]Kiribati remains a unique and culturally rich nation, with its own language, traditions, and customs. Its people continue to adapt to the challenges of the modern world while preserving their heritage and way of life.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MADURAI', 			'Madurai' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_MADURAI_ADJ', 			'Pandya' UNION ALL
SELECT 'TXT_KEY_CIV5_MADURAI_TEXT', 				'The Pandya dynasty was one of the oldest Tamil dynasties of South India, flourishing mainly in the region of present-day Tamil Nadu with its capital at Madurai. Emerging as early as the 6th century BCE, the Pandyas were celebrated in ancient Tamil literature for their patronage of trade, literature, and art. They maintained maritime trade links with the Roman Empire and other regions through ports like Korkai. The dynasty experienced several phases of power, reaching its height between the 7th and 14th centuries CE when it controlled much of southern India and parts of Sri Lanka. Known for their rivalry with the Chola dynasty and Chera dynasty, the Pandyas were also patrons of the famous Meenakshi Amman Temple in Madurai. Their rule declined after invasions by the Delhi Sultanate in the 14th century, marking the end of their political dominance, though their cultural legacy endures in Tamil history and tradition.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_OKAK', 				'Okak' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_OKAK_ADJ', 				'Thule' UNION ALL
SELECT 'TXT_KEY_CIV5_OKAK_TEXT', 					'The Thule culture was an Indigenous Arctic civilization that arose around 1000 CE in what is now Alaska and spread eastward across Arctic Canada and into Greenland. Descended from earlier Paleo-Inuit groups, the Thule people were highly skilled hunters, particularly known for their advanced techniques in whaling, seal hunting, and toolmaking. They developed sophisticated technologies such as dog sleds, umiaks (large skin boats), and harpoons adapted for life in extreme polar conditions. Their migration replaced or absorbed the earlier Dorset culture, and their settlements often featured semi-subterranean houses made from whalebone and sod. By the 17th century, the Thule evolved culturally and geographically into the ancestors of the modern Inuit, leaving a significant archaeological and cultural legacy that reflects their adaptability and expertise in Arctic survival. In Viking sources, these peoples are called the Skrælingjar.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_REYKJAVIK', 			'Reykjavík' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_REYKJAVIK_ADJ', 			'Icelandic' UNION ALL
SELECT 'TXT_KEY_CIV5_REYKJAVIK_TEXT', 				'Reykjavík, the capital and largest city of Iceland, is located on the country''s southwestern coast and serves as its cultural, economic, and political center. According to Icelandic tradition, it was first settled around 874 CE by Norseman Ingólfur Arnarson, who named it "Reykjavík", meaning "Bay of Smoke", after the steam rising from nearby hot springs. For centuries, Reykjavík remained a small fishing and farming settlement until the 18th century, when it became the focus of Danish-led urban and economic development. The city grew rapidly in the 19th and 20th centuries, especially after Iceland gained home rule in 1918 and full independence from Denmark in 1944, with Reykjavík designated as the national capital. Today, it is known for its clean, modern design, geothermal energy use, vibrant arts scene, and striking natural surroundings, symbolizing the blend of tradition and innovation that defines modern Icelandic identity.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SKARA_BRAE', 			'Skara Brae' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_SKARA_BRAE_ADJ', 			'Pictish' UNION ALL
SELECT 'TXT_KEY_CIV5_SKARA_BRAE_TEXT', 				'Skara Brae is a Neolithic settlement located on the Mainland of Orkney, Scotland. Dating back to around 3100 BC, it is one of the best-preserved prehistoric villages in northern Europe. The site was uncovered by a severe storm in 1850, revealing a complex of well-built stone houses with a sophisticated drainage system, hearths, and furniture such as beds and dressers. Skara Brae provides valuable insights into the daily lives of its inhabitants, showcasing their advanced architectural and organizational skills. [NEWLINE][NEWLINE]The village likely housed between 50 to 100 people and was inhabited for several centuries before being abandoned around 2500 BC for reasons that remain unclear. Due to its exceptional preservation, Skara Brae has been designated a UNESCO World Heritage Site and has become a popular tourist attraction, offering visitors a glimpse into the ancient past and the ingenuity of its early residents in adapting to their environment.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_KESPUKWITK', 			'Kespukwitk' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_KESPUKWITK_ADJ', 			'Wabanaki' UNION ALL
SELECT 'TXT_KEY_CIV5_KESPUKWITK_TEXT', 				'The Wabanaki Confederacy was a loose affiliation of five indigenous nations situated in the area now known as the Maritime Provinces of Canada and the U.S. state of Maine. These five nations, the Mi''kmaq, Maliseet, Passamaquoddy, Abenaki and Penobscot, bound themselves together under one Grand Chief in order to protect their common goals and interests -- mainly, fishing and hunting waters. While the Wabanaki Confederacy was, as mentioned above, a loose affiliation, the member nations of the Confederacy were nothing if not fiercely loyal to each other. The Confederacy worked to protect the member nations from outside threats, such as the Iroquois, and followed the guidance of their Grand Chief.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_BAGUIO', 				'Baguio' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_BAGUIO_ADJ', 				'Igorot' UNION ALL
SELECT 'TXT_KEY_CIV5_BAGUIO_TEXT', 					'The word "Igorot" refers any of various ethnic groups in the mountains of northern Luzon, Philippines, all of whom keep, or have kept until recently, their traditional religion and way of life. Some live in the tropical forests of the foothills, but most live in rugged grassland and pine forest zones higher up. The Igorot numbered about 1.5 million in the early 21st century. Their languages belong to the northern Luzon subgroup of the Philippine languages, which belong to the Austronesian (Malayo-Polynesian) family. [NEWLINE]The Igorot peoples are Austronesians. They were known in earlier days for their wars and practice of headhunting. The Spaniards forcibly partially subdued them during the colonial occupation of the Philippines, that process being completed during the period of U.S. hegemony. Ethnologists distinguish about 10 main ethnic groups, each with its own dialect and culture. There are also variations within these groups. [NEWLINE]Two broader groupings may be made of the Igorot as a whole: one, by far the larger, comprises the peoples of the higher country who cultivate wet rice, mostly in steplike terraces on the mountainsides; the other comprises peoples of the lower rainforest areas, who grow dry rice in seasonally shifting gardens. Within the first group the Nabaloi or Ibaloi, Kankanay (Kankanai), Lepanto or northern Kankanay, Bontoc (Bontok), southern Kalinga, and Tinggian nearly all live in populous villages, but one ethnic unit, the Ifugao, has small farmsteads of kinsmen dotted throughout the rice terraces. The second group-the Gaddang, northern Kalinga, and Isneg or Apayao-are sparsely settled in hamlets or farmsteads around which new gardens are cleared as the soil is worked out; some Gaddang live in tree houses.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ABALESSA', 			'Abalessa' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_ABALESSA_ADJ', 			'Tuareg' UNION ALL
SELECT 'TXT_KEY_CIV5_ABALESSA_TEXT', 				'The Tuareg, a seminomadic, Islamic people who speak a Berber language, Tamacheq, live in the contemporary nation-states of Niger, Mali, Algeria, and Libya. They are believed to be descendants of the North African Berbers and to have originated in the Fezzan region of Libya but later to have expanded into areas bordering the Sahara, assimilating into their traditionally stratified society the sedentary farming peoples from regions south of the Sahara. Tuareg traded with these populations and also raided them for slaves. Thus, Tuareg display diverse physical and cultural traits ranging from Arabic influences to influences stemming from south of the Sahara. "Tuareg," the term by which they are most commonly known today, is actually a term of outside, possibly Arabic origin. It was imposed as a gloss, or cover-term, to designate the ethnicity and culture of a people who, although unified by their common language and culture, belong to diverse social strata based on descent, have different geographic origins, and practice varied subsistence patterns of stock-breeding, oasis gardening, caravanning, professional Quranic scholarship, and smithing.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_AZEBA', 				'Azeba' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_AZEBA_ADJ', 				'Sabaean' UNION ALL
SELECT 'TXT_KEY_CIV5_AZEBA_TEXT', 					'Saba (also given as Sheba) was a kingdom in southern Arabia (region of modern-day Yemen) which flourished between the 8th century BCE and 275 CE when it was conquered by the neighboring Himyarites. Although these are the most commonly accepted dates, various scholars have argued for a longer or shorter chronology with the earliest date of c. 1200 BCE; most agree on the terminus of c. 275 CE, however. In its prime, however, Saba was known as a wealthy kingdom which grew rich through trade along the Incense Routes between southern Arabia and the port of Gaza on the Mediterranean Sea. Most of the biblical and quranic references - including the tale of the famous queen, the Queen of Sheba - reference Saba''s wealth and success in trade. [NEWLINE][NEWLINE]Prior to the 8th century BCE, trade in the area seems to have been controlled by the Mineans of the kingdom of Ma''in but c. 950 BCE the Sabeans dominated the region and taxed the goods heading north from their southern neighbors of Hadramawt, Qataban, and the port of Qani. Sabean trade suffered during the Ptolemaic Dynasty of Egypt (323-30 BCE) when the Ptolemies encouraged sea routes over land travel, and Saba''s prestige declined until they were conquered by the neighboring Himyarites.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_GABORONE', 			'Gaborone' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_GABORONE_ADJ', 			'Botswanan' UNION ALL
SELECT 'TXT_KEY_CIV5_GABORONE_TEXT', 				'Botswana, country in the centre of Southern Africa. The territory is roughly triangular-approximately 600 miles (965 km) from north to south and 600 miles from east to west-with its eastern side protruding into a sharp point. Its eastern and southern borders are marked by river courses and an old wagon road; its western borders are lines of longitude and latitude through the Kalahari, and its northern borders combine straight lines with a river course. Within the confines of Botswana''s borders is a rich variety of wildlife, including many species of mammals, birds, reptiles, amphibians, and fish.[NEWLINE][NEWLINE]Before its independence in 1966, Botswana was a British protectorate known as Bechuanaland. It was also one of the poorest and least-developed states in the world. The country is named after its dominant ethnic group, the Tswana ("Bechuana" in older variant orthography). Since its independence the Republic of Botswana has gained international stature as a peaceful and increasingly prosperous democratic state. It is a member of the United Nations, the Commonwealth, the African Union (AU), and the Southern African Development Community (SADC). The secretariat of SADC is housed in the capital of Botswana, Gaborone (until 1969 spelled Gaberones-i.e., Gaborone''s town, after the tribal chief who had his capital at the site during the colonial period).' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_PEGU', 				'Pegu' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_PEGU_ADJ', 				'Pegu' UNION ALL
SELECT 'TXT_KEY_CIV5_PEGU_TEXT', 					'The Hanthawaddy Kingdom (also Rone Hongsarwatoi or simply Pegu) was the polity that ruled lower Burma (Myanmar) from 1287 to 1539 and from 1550 to 1552. Hanthawaddy is the old name of the city of Pegu, nowadays Bago, the capital of the Mon-speaking kingdom (1369-1538, 1550-1552). [NEWLINE]The earliest extant evidence of Pegu as a place dates only to the late Pagan period (1212 and 1266) when it was still a small town, not even a provincial capital. After the collapse of the Pagan Empire, Pegu became part of the breakaway Kingdom of Martaban by the 1290s. [NEWLINE]The small settlement grew increasingly important in the 14th century as the region became most populous in the Mon-speaking kingdom. In 1369, King Binnya U made Pegu the capital. During the reign of King Razadarit, Pegu and the Ava Kingdom were engaged in the Forty Years'' War. The peaceful reign of Queen Shin Sawbu came to an end when she chose the Buddhist monk Dhammazedi (1471-1492) to succeed her. Under Dhammazedi, Pegu became a centre of commerce and Theravada Buddhism. [NEWLINE]The city remained the capital until the kingdom''s fall in 1538. The ascendant Toungoo dynasty under Tabinshwehti made numerous raids that the much larger kingdom could not muster its resources against. While the kingdom would have a brief resurgence for 2 years in the 1550s, Tabinshwehti''s successor Bayinnaung would firmly come to control Pegu in 1553.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_LUXEMBOURG', 			'Luxembourg' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_LUXEMBOURG_ADJ', 			'Luxembourgish' UNION ALL
SELECT 'TXT_KEY_CIV5_LUXEMBOURG_TEXT', 				'The history of Luxemburg starts in 963, when Count Siegfried acquired the Bockfiels ("Bock" in English), a promontory in the north-eastern corner of Luxembourg City, topped by the ruined, supposedly Roman, Lucilinburhuc fortification. Siegfried built a new castle on the site of the ruins, which dominated a stretch of the old Roman road linking Reims, Arlon and Trier that provided prospects for trade and taxation. During the following years, a small town and market grew around the new castle. The settlement soon received additional protection by the construction of a first and partial city wall and moat. Siegfried''s descendants of the Ardennes-Verdun dynasty (Wigeriche) extended the fortress and began to call themselves Counts of Luxembourg from the 11th century onwards. When in 1136 the Ardennes-Luxembourg branch became extinct, the county passed to the House of Namur and ultimately Countess Ermesinde, who started the House of Luxembourg, which would provide three Holy Roman Emperors. [NEWLINE][NEWLINE]Over centuries, it came under the control of various powers, including the Burgundians, Habsburgs, French, and Prussians. In 1839, the Treaty of London established Luxembourg''s independence and fixed its borders, dividing the territory between Belgium and the Grand Duchy. Despite its neutrality, it was occupied during both World Wars. Post-World War II, Luxembourg emerged as a founding member of the United Nations, NATO, and the European Union, evolving into a prosperous and politically stable nation known for its finance sector and cultural heritage.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_NYENI', 				'Niani' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_NYENI_ADJ', 				'Manden' UNION ALL
SELECT 'TXT_KEY_CIV5_NYENI_TEXT', 					'The Mali Empire, or Manden, was an empire in West Africa from circa 1235 to 1670. The empire was founded by Sundiata Keita, and became renowned for the wealth of its rulers, especially Mansa Musa. The Manding languages were spoken in the empire. At its peak, Mali was the largest empire in West Africa. The empire began a small Mandinka kingdom at the upper reaches of the Niger River, centered around the Manding. During the 11th and 12th centuries, it began to develop as an empire following the decline of the Ghana Empire, or Wagadu, to the north. However, from 1507 onwards neighboring states such as Diara, Great Fulo and the Songhay Empire chipped away at the outer borders of Mali. After unsuccessful attempts by Mansa Mama Maghan to conquer Bamana, in 1670 the Bamana sacked and burned the capital, and the Mali Empire rapidly disintegrated and ceased to exist.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_POMBERUK', 			'Pomberuk' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_POMBERUK_ADJ', 			'Ngarrindjeri' UNION ALL
SELECT 'TXT_KEY_CIV5_POMBERUK_TEXT', 				'The Ngarrindjeri are an Aboriginal group who lives along the lower Murray River and the Coorong in the modern-day state of South Australia. The Ngarrindjeri are a diverse group that comprises eighteen territorial clans, known as "lakalinyeri"; each lakinyeri is governed by a council of elders known as tendi, and the tendi elect a leader, titled the rupulli, who administers the entire Ngarrindjeri confederacy. The level of cohesion among the lakalinyeri is debated; some scholars argue that "Ngarrindjeri" is an ahistorical umbrella term imposed by European colonists. [NEWLINE][NEWLINE]The Ngarrindjeri first arrived in their traditional territory around 8000 BC. Due to the fertility of these lands, they were able to maintain a semi-sedentary lifestyle, in which they largely sustained themselves through hunting and fishing. The Ngarrindjeri were famed for their high-quality nets, which were used to catch fish and emu, as well as for their efficient oven mounds. A wide range of taboos, known as ngarambi, govern which animals are permissible to eat and by whom.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_UGARIT', 				'Ugarit' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_UGARIT_ADJ', 				'Ugaritan' UNION ALL
SELECT 'TXT_KEY_CIV5_UGARIT_TEXT', 					'Ugarit was an ancient city-state located on the eastern Mediterranean coast in what is now modern-day Syria. It emerged as a major cultural and economic center during the Late Bronze Age, flourishing from approximately the 14th to the 12th century BCE. [NEWLINE]The history of Ugarit is primarily known through its extensive archives, which consisted of clay tablets written in a cuneiform script called Ugaritic. These tablets provide valuable insights into the city''s political, social, economic, and religious aspects. [NEWLINE]Ugarit likely began as a small settlement and gradually grew in importance due to its strategic location as a maritime trading hub. It engaged in trade with various civilizations, including Egypt, Cyprus, Anatolia, and the Hittite Empire. The city became renowned for its prosperity, wealth, and cultural exchange. [NEWLINE]Around the 14th century BCE, Ugarit came under the influence of the powerful Hittite Empire, which sought to control trade routes and establish alliances in the region. Ugarit maintained a degree of independence while maintaining diplomatic and economic ties with the Hittites. [NEWLINE]The city reached its peak during the 13th century BCE when it enjoyed economic prosperity and artistic achievements. The Ugaritic language and script flourished, and the city became a center of religious worship, with temples dedicated to various gods, including Baal, Dagon, and El. [NEWLINE]However, Ugarit''s prosperity came to an abrupt end in the early 12th century BCE. The city was attacked and destroyed, possibly by a combination of invading Sea Peoples, internal unrest, and natural disasters. Ugarit was left in ruins, and its archives were preserved by the fire that consumed the city, providing invaluable historical and linguistic information for modern scholars. [NEWLINE]The decline and destruction of Ugarit marked the end of its prominence in the ancient world. The city was abandoned and gradually faded into obscurity, with subsequent civilizations building upon its ruins. [NEWLINE]Today, archaeological excavations have revealed the impressive remains of Ugarit, offering glimpses into the once-flourishing civilization. The discoveries made at Ugarit have significantly contributed to our understanding of the ancient Near East, its trade networks, social structures, religious beliefs, and the development of the cuneiform writing system.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DIEGO_GARCIA', 		'Diego Garcia' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_DIEGO_GARCIA_ADJ', 		'Chagossian' UNION ALL
SELECT 'TXT_KEY_CIV5_DIEGO_GARCIA_TEXT', 			'Chagos was first discovered by the Maldivan Sultanates to the north, where sailors would come adrift on the tropical shores of the Great Chagos Bank, naming the land Folhavahi. In the great Age of Exploration, Portuguese seafarers named the archipelago Bassas de Chagas, a name referring to the Holy Wounds of Jesus''s Crucifixion. However, the islands were economically unprofitable compared to the richer islands to the north and east, and so it remained bare for years to come. In 1771, the French Empire laid a claim to the islands, establishing cocunut oil plantations. This attracted the attention of the British, who claimed the islands in 1786, eventually taking control of them afer Napoleon''s defeat in 1814. The islands remained a subject of the British Empire for well over a hundred years, absorbed into the administrative territory of Mauritius. Descendents of slaves who had worked the coconut plantations inhabited the islands peacefully, living Spartan lives on the beaches and jungles. However, in 1965 with Mauritius being granted self-government, the UK purchased the archipelago with the intent to remove the plantations, installing a United States Military Base. Between 1967 and 1973, the entire population of Chagos was forcibly moved to either the Seychells or Mauritius, often ending up to sleep in rough housing and withstand poor living conditions.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_GUNGNAE', 			'Gungnae' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_GUNGNAE_ADJ', 			'Goguryeo' UNION ALL
SELECT 'TXT_KEY_CIV5_GUNGNAE_TEXT', 				'Goguryeo, also known as Koguryo or Goryeo, was one of the Three Kingdoms of ancient Korea, founded in 37 BCE by King Dongmyeong (also known as Jumong) in the northern part of the Korean Peninsula and southern Manchuria. Over the centuries, it expanded into a powerful military state, controlling vast territories and becoming a dominant force in Northeast Asia. Goguryeo was renowned for its formidable fortresses, advanced military organization, and rich culture influenced by both native traditions and Chinese civilization. The kingdom frequently clashed with Chinese dynasties and neighboring Korean states, particularly Baekje and Silla. At its peak in the 5th century under King Gwanggaeto the Great and his son King Jangsu, Goguryeo ruled much of Manchuria and northern Korea. However, internal strife and external pressure from the Tang dynasty and Silla alliance led to its fall in 668 CE. Goguryeo''s legacy profoundly shaped Korean culture, identity, and historical consciousness, symbolizing strength and independence.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MACACO', 				'Macaco' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_MACACO_ADJ', 				'Palmarista' UNION ALL
SELECT 'TXT_KEY_CIV5_MACACO_TEXT', 					'Palmares was a quilombo, a makeshift society comprised primarily of runaway slaves in the hinterlands of colonial South America. The larger of these communities took the shape of organized kingdoms based on contemporary African styles of governance, and even began their own hereditary monarchies. Palmares was by far the largest and most successful of the quilombos, lasting almost a century from its establishment in 1605 to its eventual defeat in 1694. Estimations of the Palmarista population vary, ranging between 10,000 and 20,000 citizens at its peak. As Palmares was frequently raided by the Portuguese colonial authorities, cultural history has it as the origin point of the Afro-Brazilian martial art known as capoeira. By Portuguese accounts, "it is harder to defeat a quilombo than the Dutch invaders".' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MANTHIMBA', 			'Manthimba' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_MANTHIMBA_ADJ', 			'Maravi' UNION ALL
SELECT 'TXT_KEY_CIV5_MANTHIMBA_TEXT', 				'Maravi was a kingdom which straddled the current borders of Malawi, Mozambique, and Zambia, in the 16th century. The present-day name "Maláwi" is said to derive from the Chewa word "malawí", which means "flames". [NEWLINE]At its greatest extent, the state included territory from the Tonga and Tumbuka people''s areas in the north to the Lower Shire in the south, and as far west as the Luangwa and Zambezi river valleys. Maravi''s rulers belonged to the Mwale matriclan and held the title Kalonga. They ruled from Manthimba, the secular/administrative capital, and were the driving force behind the state''s establishment. Meanwhile, the patrilineal Banda clan, which traditionally provided healers, sages and metallurgists, took care of religious affairs from their capital Mankhamba near Nthakataka. [NEWLINE]After contact with the Portuguese, trade intensified. It included such items as beads of the Khami type and Chinese porcelain imported via Portuguese intermediaries. In the 19th century, the state declined and the Maravi were frequently raided by their neighbours the Yao and captured for sale as slaves. David Livingstone visited Lake Nyasa in 1859, and other Protestant missionaries soon followed. ' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ORISTANO', 			'Oristano' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_ORISTANO_ADJ', 			'Arborense' UNION ALL
SELECT 'TXT_KEY_CIV5_ORISTANO_TEXT', 				'The Judicate of Arborea, also known as the Kingdom of Arborea, was a medieval state located on the island of Sardinia, off the coast of Italy. It existed from the 11th to the 15th century and played a significant role in the island''s history. [NEWLINE]The origins of the Judicate of Arborea can be traced back to the Giudicato of Cagliari, an earlier political entity that fragmented into several smaller states known as judicatures or giudicati. Arborea emerged as one of the most prominent judicatures and eventually gained independence. [NEWLINE]Under the rule of the Giudici, or judges, the Judicate of Arborea thrived and developed a distinct legal system known as the "Carta de Logu." This legal code, established by the judge Eleanor of Arborea in the 14th century, provided a comprehensive framework for governance and established a set of laws and rights for the people of Arborea. [NEWLINE]Arborea expanded its territories through military conquest and diplomacy, at times clashing with other Sardinian judicatures, as well as with foreign powers seeking control over the island. It maintained a degree of autonomy, forging alliances and engaging in trade with neighboring states. [NEWLINE]The Judicate of Arborea reached its height of power and influence in the 14th century, under the rule of Judge Peter IV. His reign saw the judicate assert its independence from external powers and successfully resist attempts by the Crown of Aragon to conquer the island. [NEWLINE]However, Arborea faced internal conflicts and external pressures in the following centuries. The judicate experienced a decline in the face of the expanding Kingdom of Aragon, which sought to consolidate its control over Sardinia. In 1410, the last independent judge of Arborea, William III, was captured by the Aragonese forces, effectively ending the political independence of Arborea. [NEWLINE]Afterward, Arborea became a part of the Kingdom of Sardinia, which eventually came under the rule of the Spanish Habsburgs and later the House of Savoy. The distinct legal and cultural legacy of Arborea, including the Carta de Logu, left a lasting impact on Sardinia. [NEWLINE]Today, the history and cultural heritage of the Judicate of Arborea are recognized and celebrated in Sardinia, with various historical sites and festivals commemorating this important period in the island''s past.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_PONTOTOC', 			'Pontotoc' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_PONTOTOC_ADJ', 			'Chickasaw' UNION ALL
SELECT 'TXT_KEY_CIV5_PONTOTOC_TEXT', 				'The Chickasaw are a North American Indian tribe of Muskogean linguistic stock who originally inhabited what is now northern Mississippi and Alabama. In their earlier history the Chickasaw and the Choctaw may have been a single tribe. Traditionally, the Chickasaw were a seminomadic people who patrolled the immense territory that they claimed for themselves and raided tribes far to the north; like many conquering peoples, they integrated the remnants of these tribes into their culture.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_PURUKCAHU', 			'Puruk Cahu' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_PURUKCAHU_ADJ', 			'Dayak' UNION ALL
SELECT 'TXT_KEY_CIV5_PURUKCAHU_TEXT', 				'The Dayak are one of the native groups of Borneo. It is a loose term for over 200 riverine and hill-dwelling ethnic subgroups, located principally in the central and southern interior of Borneo. The term encompasses a number of dialects, customs, laws, territories and cultures, although common distinguishing traits are readily identifiable. Traditionally the Dayak were Animist, although throughout history there have been mass conversions to both Islam and Christianity. The history of the Dayak is rooted mostly in an oral history tradition, although there are a number of written work upon papan turai (wooden records), as well as the passing down of common cultural practices. Among prominent accounts of the origin of the Dayak people is the mythical oral epic of "Tetek Tahtum" by the Ngaju Dayak of Central Kalimantan; it narrates that the ancestors of the Dayak people descended from the heavens before moving from inland to the downstream shores of Borneo.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SCODRA', 				'Scodra' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_SCODRA_ADJ', 				'Illyrian' UNION ALL
SELECT 'TXT_KEY_CIV5_SCODRA_TEXT', 					'The Illyrians were a group of Indo-European tribes in antiquity, who inhabited part of the western Balkans. The territory the Illyrians inhabited came to be known as Illyria to Greek and Roman authors, who identified a territory that corresponds to Croatia, Bosnia and Herzegovina, Slovenia, Montenegro, Kosovo,[a] part of Serbia and most of central and northern Albania, between the Adriatic Sea in the west, the Drava river in the north, the Puruk Cahuva river in the east and the mouth of the Aoos river in the south. The first account of Illyrian peoples comes from the Periplus of Pseudo-Scylax, an ancient Greek text of the middle of the 4th century BC that describes coastal passages in the Mediterranean.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_TETOUAN', 			'Tétouan' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_TETOUAN_ADJ', 			'Tétouan' UNION ALL
SELECT 'TXT_KEY_CIV5_TETOUAN_TEXT', 				'The history of Tétouan (or Tetouan) stretches over 2000 years to its origins as a Mauretanian Berber settlement named Tamuda, located at near present-day Tetouan by the south bank of the Martil Valley. The site later became a Phoenician trading post. During the time of Emperor Augustus, Tamuda became part of Roman province Mauritania Tingitana. In 1286, the Marinids built a casbah and mosque there. The first large scale building project took place in 1305 when the settlement was expanded by the Marinid king Abu Thabit Amir. He fortified the place and had it serve as a base for attacks on Ceuta, which had recently come under the rule of a rebellious member of the Marinid dynasty.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_TILANTONGO', 			'Tilantongo' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_TILANTONGO_ADJ', 			'Mixtec' UNION ALL
SELECT 'TXT_KEY_CIV5_TILANTONGO_TEXT', 				'The Mixtecs, or Mixtecos, are indigenous Mesoamerican peoples of Mexico inhabiting the region known as La Mixteca of Oaxaca and Puebla as well as the state of Guerrero''s Región Montañas, and Región Costa Chica, which covers parts of the Mexican states of Oaxaca, Guerrero and Puebla. In pre-Columbian times, a number of Mixtecan city states competed with each other and with the Zapotec kingdoms. The major Mixtec polity was Tututepec which rose to prominence in the 11th century under the leadership of Eight Deer Jaguar Claw, lord of Tilantongo and the only Mixtec king who ever united the Highland and Lowland polities into a single state. Like the rest of the indigenous peoples of Mexico, the Mixtec were conquered by the Spanish invaders and their indigenous allies in the 16th century. Pre-Columbian Mixtecs numbered around 1.5 million. Today there are approximately 800,000 Mixtec people in Mexico, and there are also large populations in the United States. The term Mixtec comes from the Nahuatl word mixtecah, "cloud people". There are many names that the Mixtecs have for naming themselves: ñuù savi, nayívi savi, ñuù davi, nayivi davi. etc. All these denominations can be translated as "the land of the rain".' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_VAITAPE', 			'Vaitape' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_VAITAPE_ADJ', 			'Bora-Bora' UNION ALL
SELECT 'TXT_KEY_CIV5_VAITAPE_TEXT', 				'The Kingdom of Bora-Bora was first documented by explorer Jakob Roggeveen, in 1722. However, James Cook was the person who first made contant with the Bora-Bora people, in 1769. This was when Puni was in power. Bora-Bora had a rivalry of two clans, Sons of Hiro and Vaiotaha (they were the maraes used by the two clans). Puni was part of the Sons of Hiro clan, and gained control of Bora-Bora, and was even able to conquer Tupai, Ra''iatea, Taha''a, Maupiti, Huahine, Motu One, Manua''e, and Maupihaa. This was Bora-Bora''s greatest extent. With Puni''s death, his nephew, Topa I, ruled, but the islands were ruled with very poor authority under her rule, so the islands slowly feel into disunity.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_AVI_KWA_AME', 		'Avi Kwa Ame' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_AVI_KWA_AME_ADJ', 		'Mohave' UNION ALL
SELECT 'TXT_KEY_CIV5_AVI_KWA_AME_TEXT', 			'The Mohave are a Native American people indigenous to the Colorado River in the Mojave Desert. The Fort Mojave Indian Reservation includes territory within the borders of California, Arizona, and Nevada. The Colorado River Indian Reservation includes parts of California and Arizona and is shared by members of the Chemehuevi, Hopi, and Navajo peoples. The original Colorado River and Fort Mojave reservations were established in 1865 and 1870, respectively. Both reservations include substantial senior water rights in the Colorado River; water is drawn for use in irrigated farming. The four combined tribes sharing the Colorado River Indian Reservation function today as one geo-political unit known as the federally recognized Colorado River Indian Tribes; each tribe also continues to maintain and observe its individual traditions, distinct religions, and culturally unique identities.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_CAHUACHI', 			'Cahuachi' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_CAHUACHI_ADJ', 			'Nazca' UNION ALL
SELECT 'TXT_KEY_CIV5_CAHUACHI_TEXT', 				'The Nazca culture is a pre-Columbian Peruvian culture who flourished between c. 100 BC and c. 800 AD. Influenced a great deal by the preceding Paracas culture, who are known for their complex textiles, the Nazca created an impressive collection of crafts and technologies including ceramics, textile and geoglyphs - the most common of these being the Nazca Lines. They also created a vast system of underground aqueducts that still function to this day.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_CAIRO', 				'Cairo' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_CAIRO_ADJ', 				'Fatimid' UNION ALL
SELECT 'TXT_KEY_CIV5_CAIRO_TEXT', 					'The Fatimid Caliphate was an Islamic dynasty that ruled a vast empire from 909 to 1171 CE, founded in North Africa by followers of the Isma''ili branch of Shia Islam who claimed descent from Fatimah, the daughter of the Prophet Muhammad. Initially established in present-day Tunisia, the Fatimids expanded their control across North Africa, Sicily, and the Levant, eventually founding the city of Cairo in 969 CE, which became their political and cultural capital. The caliphate flourished as a center of trade, scholarship, and religious tolerance, fostering advancements in science, medicine, architecture, and the arts. The Fatimids built monumental structures such as Al-Azhar Mosque, which became one of the world''s leading centers of Islamic learning. However, internal divisions, economic challenges, and growing military pressure from the Seljuks and Crusaders weakened the state, leading to its eventual decline and replacement by the Sunni Ayyubid dynasty under Saladin in 1171.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_CAMUTINS', 			'Camutins' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_CAMUTINS_ADJ', 			'Marajoara' UNION ALL
SELECT 'TXT_KEY_CIV5_CAMUTINS_TEXT', 				'Known since the nineteenth century for its elaborate polychrome funerary pottery and numerous monumental earthen mounds, the Marajoara culture at the mouth of the Amazon in Brazil was attributed by early professional archaeologists to an invasion from the Andes, because the tropical forest was considered to be too poor to support large human populations and complex cultures. However, the habitat of the Marajoara is not terra firme (upland) tropical forest lowland but floodplain, so the influence of the habitat need not have been as limiting as assumed earlier. The culture has now been dated with twenty-four radiocarbon dates, and these reveal that the culture is earlier than related Andean cultures, and the physical anthropology of the people affiliates them with Amazonian populations, rather than Andeans. Thus, Marajoara now must be presumed a local development of the tropical lowlands. The Marajoara mounds had been characterized by earlier archaeologists as purely ceremonial, but recent geophysical surveys and excavations show them to be large platforms for entire villages of earth, pole, and thatch longhouses with adjacent cemeteries and garbage dumps. The fishbones, seeds, and tools of exotic rocks in the mounds indicate a mixed economy of fishing, gathering, trade, and horticulture, and several carbonized maize specimens were recovered in the excavations.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DONGOLA', 			'Dongola' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_DONGOLA_ADJ', 			'Makurian' UNION ALL
SELECT 'TXT_KEY_CIV5_DONGOLA_TEXT', 				'Makuria was a medieval Christian kingdom located in the Nubian region of what is now northern Sudan and southern Egypt, flourishing from around the 6th to the 14th century CE. Centered in its capital, Dongola, Makuria emerged after the decline of the ancient Nubian kingdoms and adopted Christianity, likely through Byzantine and Coptic influence, becoming a stronghold of the faith in the Nile Valley. The kingdom is best known for its remarkable diplomatic and military resilience, particularly its successful defense against early Arab-Muslim invasions in the 7th century, which led to the Baqt treaty, a long-lasting peace and trade agreement with Egypt that preserved Makuria''s independence for centuries. During its height, Makuria maintained a prosperous economy based on agriculture, trade, and skilled craftsmanship, and it developed a distinctive Nubian Christian culture. However, internal strife, environmental pressures, and increasing Islamic influence gradually weakened the kingdom, leading to its decline and eventual absorption by Muslim powers by the 14th century.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_GONDAR', 				'Gondar' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_GONDAR_ADJ', 				'Simien' UNION ALL
SELECT 'TXT_KEY_CIV5_GONDAR_TEXT', 					'The Kingdom of Simien, sometimes referred to as the Kingdom of Beta Israel, was an ancient kingdom of the Beta Israeli population centered in the northwestern part of the Ethiopian Empire that came to an end in 1627 during the reign of Ethiopian Emperor Susenyos I. There is a disagreement regarding the exact time of the establishment of the kingdom; it was preceded by a number of regions which were in Jewish rule in the northwestern part of Ethiopia. The Jewish-Ethiopian tradition dates the establishment of the Kingdom of Semien to the fourth century, right after the kingdom of Axum turned to Christianity during the reign of Ezana of Axum. [NEWLINE][NEWLINE]The Golden Age of the Beta Israel kingdom took place, according to the Ethiopian tradition, between the years 858-1270, in which the Jewish kingdom flourished. During that period the world Jewry heard for the first time the stories of Eldad ha-Dani who apparently visited the kingdom. Marco Polo and Benjamin of Tudela also mention an independent Ethiopian Jewish kingdom in the writings from that period. This period ends with the rise of the Christian Solomonic dynasty.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_GROZNY', 				'Grozny' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_GROZNY_ADJ', 				'Vainakh' UNION ALL
SELECT 'TXT_KEY_CIV5_GROZNY_TEXT', 					'The Vainakhs are the only surviving branch of the Nakh peoples, a collection of peoples living in the Causcaus mountains. The two main groups of Vainakhs are the Chechens and Ingush, who presently live mostly within their respective ethnic republics within the larger Russian republic. The Vainakhs are a very ancient people, possible relatives of the ancient Hurrians and Uartians the Vainakhs have frequently been threatened by greater powers than them, such as the Scythians, Mongols and Russians, and often fought to defend and preserve their culture and way of life. Traditionally, the Vainakh social structure was based on highly democratic clans known as Teips which formed military-political unions known as Tukkhum. There was also a peoples council that functioned at the national scale. Despite numerous atrocities the Chechens and Ingush still maintain a strong identity and a fervent belief in equality and freedom, which are integral to their traditional way of life.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MATONJENI', 			'Matonjeni' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_MATONJENI_ADJ', 			'Kalanga' UNION ALL
SELECT 'TXT_KEY_CIV5_MATONJENI_TEXT', 				'The Njelele Shrine or Matonjeni is an emblematic sacred site in Zimbabwe and bears profound cultural and spiritual significance rooted in the traditions of rainmaking rituals and ancestral veneration. Revered by local communities for its role in facilitating communication with ancestral spirits and petitioning for rain and agricultural abundance, the shrine embodies centuries-old beliefs and practices passed down through generations. Matonjeni is also related to the cult of Mwari (Mwali), the supreme creator deity according to Shona and Venda traditional religion practiced in the Kingdom of Zimbabwe and in its successors Mutapa and Butua. Pilgrimages and ceremonies conducted at Njelele Shrine serve as vital communal and spiritual rites, preserving the cultural heritage and traditions of Zimbabwe''s indigenous peoples while fostering a deep connection to their ancestral past and the natural world.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SOMBAKE', 			'Somba K''e' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_SOMBAKE_ADJ', 			'Dene' UNION ALL
SELECT 'TXT_KEY_CIV5_SOMBAKE_TEXT', 				'The Dene are a native people heralding mainly from the vast frozen northern regions of what is now modern-day Canada, although they also lived in certain areas now belonging to the U.S., particularly the state of Alaska. Composed of many various tribes, most notably the Chipewyan, Tlicho, Yellowknives, Slavey and Sahtu peoples, although the ranks of Dene are not limited to these groups. With that said, a number of the tribes once associated with the Dene have become extinct, such as Tsetsaut people, who were located in what is now the Portland Canal area, close to the Alaskan border. The Dene were the first people to settle in the Northwest Territories, which they refer to as Denendeh.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_TURA', 				'Tura' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_TURA_ADJ', 				'Evenki' UNION ALL
SELECT 'TXT_KEY_CIV5_TURA_TEXT', 					'The Evenks are an Indigenous people of northern Asia, traditionally inhabiting vast regions of Siberia in Russia, as well as parts of northeastern China and Mongolia. Belonging to the Tungusic language family, the Evenks have historically been semi-nomadic reindeer herders, hunters, and trappers, adept at surviving in the taiga and tundra through deep knowledge of their natural environment. Their culture is rich in shamanistic beliefs, emphasizing harmony with nature and reverence for spirits. The Evenks first came into contact with Russian explorers and traders in the 17th century during Russia''s eastward expansion, which brought significant cultural and economic changes, including the fur trade and eventual incorporation into the Russian Empire. Soviet-era policies further transformed their traditional way of life through forced settlement and collectivization. Today, the Evenks continue to face challenges related to cultural preservation and environmental threats to their lands, yet they remain an important part of the cultural and ethnic mosaic of northern Eurasia.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_YIRRKALA', 			'Yirrkala' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_YIRRKALA_ADJ', 			'Yolngu' UNION ALL
SELECT 'TXT_KEY_CIV5_YIRRKALA_TEXT', 				'The Yolngu are an Indigenous people of northeastern Arnhem Land in Australia''s Northern Territory, with a deep cultural, linguistic, and spiritual heritage that dates back tens of thousands of years. They are composed of numerous clans and speak several Yolngu Matha languages, maintaining complex kinship systems and strong connections to their ancestral lands, known as Country. Yolngu society is guided by traditional law (Madayin) and rich ceremonial life, including songlines, dance, and art that express relationships between people, land, and the Dreaming, the spiritual origin of existence. The Yolngu were among the first Indigenous Australians to encounter outsiders, including Macassan traders from Indonesia who visited their coasts for centuries before European colonization. In the modern era, the Yolngu have played a key role in the Indigenous rights movement, notably through the 1963 Yirrkala Bark Petitions, the first formal assertion of Aboriginal land rights presented to the Australian Parliament. Today, they continue to preserve their culture while navigating contemporary challenges and advocating for self-determination.' UNION ALL
--=====================================================================
SELECT 'TXT_KEY_CITYSTATE_TULA', 				'Tula' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_TULA_ADJ', 				'Toltec' UNION ALL
SELECT 'TXT_KEY_CIV5_TULA_TEXT', 					'The Toltecs were a precolumbian civilization that dominated Mesoamerica during the early post-classic period. The Toltecs are one of the greatest mysteries of Mesoamerica, what little information we have concerning them is derived from Aztec mythology and archeology. Nahuatl myth claims the Toltecs to have been an empire of artisans and soldiers, ushering in an era of technological and cultural revolution, one that the Aztecs themselves wished to emulate. Though modern scholars are skeptical of the presence of a Toltec "empire", archeology reveals that there was a powerful kingdom centred around the historical capital Tula. Evidence shows that Tula had access to lucrative trade networks, and the site features complexes, palaces and iconography typical of imperial Mesoamerican states.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ZENU', 				'Zenú' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_ZENU_ADJ', 				'Zenú' UNION ALL
SELECT 'TXT_KEY_CIV5_ZENU_TEXT', 					'The Zenú, also known as the Sinú, are an Indigenous people of northern Colombia whose ancestral lands lie in the fertile river valleys of the Sinú, San Jorge, and Cauca rivers. Their civilization flourished between roughly 200 BCE and 1600 CE, developing one of the most sophisticated pre-Columbian hydraulic systems in the Americas, vast networks of canals and raised fields that supported intensive agriculture and dense populations. The Zenú were also skilled goldsmiths, producing exquisite metalwork that reflected their complex social and spiritual life. With the arrival of the Spanish in the 16th century, their political structures collapsed, and many communities were displaced or assimilated. Despite centuries of marginalization, the Zenú have maintained strong cultural traditions, including weaving and community governance, and today they are officially recognized as an Indigenous group in Colombia, reclaiming land and cultural rights while preserving the legacy of their remarkable engineering and artistry.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_HALICARNASSUS', 		'Halicarnassus' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_HALICARNASSUS_ADJ', 		'Carian' UNION ALL
SELECT 'TXT_KEY_CIV5_HALICARNASSUS_TEXT', 			'Caria was a region of western Anatolia extending along the coast from mid-Ionia south to Lycia and east to Phrygia. The Ionian and Dorian Greeks colonized the west of it and joined the Carian population in forming Greek-dominated states there. [NEWLINE]Caria was incorporated into the Persian Achaemenid Empire as a satrapy (province) in 545 BC. The most important town was Halicarnassus, from where its sovereigns, the tyrants of the Lygdamid dynasty (c.520-450 BC), reigned. Other major towns were Latmus, refounded as Heracleia under Latmus, Antiochia, Myndus, Laodicea, Alinda and Alabanda. Caria participated in the Ionian Revolt (499-493 BC) against the Persian rule.[NEWLINE][NEWLINE]During the Second Persian invasion of Greece (480-479 BC), the cities of Caria were allies of Xerxes I and they fought at the Battle of Artemisium and the Battle of Salamis, where the Queen of Halicarnassus Artemisia commanded the contingent of 70 Carian ships. Themistocles, before the battles of Artemisium and Salamis, tried to split the Ionians and Carians from the Persian coalition. He told them to come and be on his side or not to participate at the battles, but if they were bound down by too strong compulsion to be able to make revolt, when the battles begin, to be purposely slack. Plutarch in his work, The Parallel Lives, at The Life of Themistocles wrote that: "Phanias writes that the mother of Themistocles was not a Thracian, but a Carian woman and her name was Euterpe, and Neanthes adds that she was from Halicarnassus in Caria."[NEWLINE][NEWLINE]After the unsuccessful Persian invasion of Greece in 479 BC, the cities of Caria became members of the Athenian-led Delian League, but then returned to Achaemenid rule for about one century, from around 428 BC. Under Achaemenid rule, the Carian dynast Mausolus took control of neighbouring Lycia, a territory which was still held by Pixodarus as shown by the Xanthos trilingual inscription.[NEWLINE][NEWLINE]Halicarnassus was the location of the famed Mausoleum dedicated to Mausolus, a satrap of Caria between 377-353 BC, by his wife, Artemisia II of Caria. The monument became one of the Seven Wonders of the Ancient World, and from which the Romans named any grand tomb a mausoleum.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ELEA', 				'Elea' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_ELEA_ADJ', 				'Eleatic' UNION ALL
SELECT 'TXT_KEY_CIV5_ELEA_TEXT', 					'Velia is the name that the Romans gave to the ancient village of Elea, founded in 540 BC by the Greeks fleeing the Persian invasion of Ionia, on the western coast of present-day Turkey.[NEWLINE]The village had been built on a promontory commanding the Tyrrhenian Sea. In Elea originated the Eleatic Philosophy School, founded by the famous philosopher Parmenide and carried on by the philosophers Zeno, Melissus, Xenophanes, Leucippus. [NEWLINE]For several centuries Velia-Elea has been the center of culture in the fields of philosophy and medicine. In the 88 BC the village became a Roman village and thereafter declined because its two ports where covered by the sand brought by the sea. The surrounding area was swallowed up by the marshes and the inhabitants left the coast to settle further from the sea, founding the village that still today is called Novi Velia. [NEWLINE][NEWLINE]In 1998 the Cilento and Vallo di Diano National Park together with the Archeological Sites of Paestum and Velia, and the Certosa di Padula was included in the UNESCO list of World Heritage sites.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SANGGYEONG', 			'Sanggyeong' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_SANGGYEONG_ADJ', 			'Balhae' UNION ALL
SELECT 'TXT_KEY_CIV5_SANGGYEONG_TEXT', 				'The Kingdom of Balhae was a political union of the semi-nomadic Mohe, Khitans, and Korean-speaking communities, which succeeded the long-lived Goguryeo kingdom, lasting from its establishment by the former Goguryeo general and Mohe chieftain Dae Joyeong (r. 699 - 719 CE) to its conquest by the Khitan confederation in 926. At its zenith, its territories reached far into the modern-day Russian Far East, encompassed the northern half of the Korean Peninsula, and extended to the Liao River in northeastern China. Although variously classed as a Tang client state, a puppet of the Japanese Emperor and an ethnic Korean state by Chinese, Japanese and Korean scholars respectively, Balhae was, as borne out by archaeology, linguistics and history, a unique multiethnic experiment in state formation that established a common identity that was to last until the destruction of its final successor state, Heungyo, in the mid-11th century.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_NELEMNOYE', 			'Nelemnoye' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_NELEMNOYE_ADJ', 			'Yukaghir' UNION ALL
SELECT 'TXT_KEY_CIV5_NELEMNOYE_TEXT', 				'The Yukaghirs are an indigenous people of northeastern Siberia, primarily inhabiting the Kolyma River basin and other parts of the Russian Far East. Historically, the Yukaghirs were one of the dominant groups in the region, with a lifestyle based on hunting, fishing, and reindeer herding. They spoke several languages within the Yukaghir family, which are considered some of the most ancient in Siberia. During the medieval period, they traded with neighboring peoples and lived relatively autonomously. However, their numbers and cultural prominence began to decline after the arrival of Russian explorers and traders in the 17th century. The imposition of the Russian fur tax (yasak) and the spread of diseases like smallpox greatly reduced their population and disrupted their traditional way of life. [NEWLINE][NEWLINE]By the 20th century, the Yukaghirs had become a minority, assimilated into neighboring groups such as the Yakuts and Evenks due to intermarriage and sociopolitical pressures. Soviet policies further contributed to their marginalization, as the Yukaghirs were often relocated to collective farms, and their traditional practices were suppressed. Today, only a few hundred people identify as Yukaghir, and their two main dialects-Tundra and Kolyma Yukaghir-are critically endangered. Efforts are being made to revitalize their language and culture, with increasing interest in preserving their oral traditions, folklore, and connection to the natural environment. The Yukaghirs are now recognized as one of the indigenous small-numbered peoples of Russia, benefiting from certain legal protections designed to safeguard their cultural and economic rights.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ORUGALLU', 			'Orugallu' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_ORUGALLU_ADJ', 			'Kakatiya' UNION ALL
SELECT 'TXT_KEY_CIV5_ORUGALLU_TEXT', 				'The Kakatiya dynasty was an Indian dynasty that ruled most of eastern Deccan region between 12th and 14th centuries. Early Kakatiya rulers served as feudatories to Rashtrakutas and Western Chalukyas for more than two centuries. They assumed sovereignty under Prataparudra I in 1163 CE. Ganapati Deva significantly expanded Kakatiya lands during the 1230s. Ganapati Deva was succeeded by Rudrama Devi, who successfully repelled the attacks of Yadavas. After the successful siege of Warangal in 1310, Prataparudra II was forced to pay annual tribute to Delhi. Another attack by Ulugh Khan in 1323 saw stiff resistance by the Kakatiyan army, but they were finally defeated.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MATURUCA', 			'Maturuca' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_MATURUCA_ADJ', 			'Macushi' UNION ALL
SELECT 'TXT_KEY_CIV5_MATURUCA_TEXT', 				'The Macushi, also known as the Makuxi, Macuxi, Macusi, Macussi, Makushi, Makusi, Teueia, and Teweya people, are an indigenous people living in the borderlands of southern Guyana, northern Brazil, eastern Venezuela.Their oral history describes them as descendants of the sun, and were semi-nomadic prior to colonisation. [NEWLINE]The Macushi live in villages linked together by tracks and paths, with houses built round a central courtyard. Macushi practice hunting and agriculture methods such as shifting cultivation and fish-poisoning. Similar to other indigenous groups in the area, Macushi traditional life relies a great deal on the bitter cassava, known in the Macushi culture as Kisera. The tasks conducted around this plant are usually divided by gender. Men traditionally clear the land and women tend and harvest. When married, the Macushi couple lives in the wife''s family''s village and the father-in-law is of great importance in Macushi kinship. [NEWLINE]The earliest recorded mentions of Macushi was in 1740 in context of Luso-Brazilian slave raids led by Irishman Lancelot Belforte, known to Brazilians as Lourenço Belforte. From the 1700s to the late 1800s, the Macushi were pushed north by Brazilian raids, and south by Caribs and Akawaio proxies for the Dutch and English, limiting the extent of their lands to the Rupununi Savannah. While there are reports of Macushi selling their own into slavery, it has also been noted that this was done under duress. In the 1800s, Macushis "specialized in producing hammocks, various crafts, and a potent form of curare" which were traded among other Amerindian groups in the region often for cassava graters and blow-pipes.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ASHDOD', 				'Ashdod' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_ASHDOD_ADJ', 				'Philistine' UNION ALL
SELECT 'TXT_KEY_CIV5_ASHDOD_TEXT', 					'The Philistines were people of Greek origin who settled on the southern coast of Palestine in the 12th century bc, about the time of the arrival of the Israelites. According to biblical tradition, the Philistines came from Caphtor (possibly Crete). They are mentioned in Egyptian records as prst, one of the Sea Peoples that invaded Egypt in about 1190 bc after ravaging Anatolia, Cyprus, and Syria. After being repulsed by the Egyptians, they occupied the coastal plain of Palestine from Joppa (modern Tel Aviv-Yafo) southward to the Gaza Strip. The area contained the five cities (the Pentapolis) of the Philistine confederacy (Gaza, Ashkelon [Ascalon], Ashdod, Gath, and Ekron) and was known as Philistia, or the Land of the Philistines. It was from this designation that the whole of the country was later called Palestine by the Greeks.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ITHACA', 				'Alalcomenae' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_ITHACA_ADJ', 				'Ithacan' UNION ALL
SELECT 'TXT_KEY_CIV5_ITHACA_TEXT', 					'Ithaca is a small Greek island in the Ionian Sea, located off the western coast of mainland Greece, renowned as the legendary home of Odysseus, the hero of Homer''s Odyssey. The island''s rugged hills, deep bays, and olive-covered slopes have long been associated with the epic tale of Odysseus''s journey home after the Trojan War, making Ithaca a powerful symbol of longing, perseverance, and return in Western literature. Historically, Ithaca was inhabited since the Bronze Age and likely part of the Mycenaean world, serving as a minor but strategically placed island in ancient maritime trade routes. It later came under the control of various powers, including the Romans, Byzantines, Venetians, and British, before becoming part of modern Greece in 1864 along with the rest of the Ionian Islands. Today, Ithaca is celebrated for its natural beauty, tranquil villages, and deep mythological heritage, attracting visitors seeking both history and the timeless spirit of Homeric adventure.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_NGYLVO', 				'Ngyl''vo' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_NGYLVO_ADJ', 				'Nivkh' UNION ALL
SELECT 'TXT_KEY_CIV5_NGYLVO_TEXT', 					'The Nivkh are an indigenous people of the Russian Far East, primarily inhabiting the northern half of Sakhalin Island and the lower Amur River basin. Traditionally, they lived as semi-nomadic hunters, fishers, and gatherers, relying heavily on the abundant salmon and other marine resources of the region. The Nivkh developed a unique culture, with rich oral traditions, intricate craftsmanship, and animistic beliefs closely tied to their environment. They had limited contact with outside groups until the 17th century when Russian explorers began to establish trade and collect tribute from the Amur Basin''s indigenous peoples. This initial contact often disrupted their traditional economy and introduced foreign influences to their society. [NEWLINE][NEWLINE]During the Soviet period, the Nivkh faced significant cultural and social upheaval. Policies of collectivization and forced sedentarization altered their traditional ways of life. Additionally, efforts to assimilate indigenous populations included the suppression of native languages and traditions. As a result, the Nivkh language, considered an isolate with no known linguistic relatives, became endangered, with Russian dominating as the primary language. Despite these challenges, the Nivkh have retained elements of their cultural identity, and recent initiatives have sought to revitalize their language and traditions. Today, the Nivkh are recognized as one of Russia''s indigenous small-numbered peoples, with ongoing efforts to preserve their heritage amidst modern challenges.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_CAILIN', 				'Cailín' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_CAILIN_ADJ', 				'Chono' UNION ALL
SELECT 'TXT_KEY_CIV5_CAILIN_TEXT', 					'The Chono, or Guaiteco were a nomadic indigenous people or group of peoples of the archipelagos of Chiloé, Guaitecas and Chonos. The Chono people lived as hunter-gatherers traveling by canoe. Much of what is known from Spanish sources on Chonos is filtered by a Huilliche (southern Mapuche) worldview, as Huilliches and Huilliche language was used to communicate with Chonos. The Chono people are believed to be Chiloé Archipelago''s first ethnically identifiable inhabitants, which has led to the assumption that the Chono were the people who left behind most of the abundant shell middens of Chiloé. There are various place names in Chiloé with Chono etymologies despite the main indigenous language of the archipelago at the arrival of the Spaniards being Veliche. As such, some historians consider that places as far north as the coast of Osorno and Llanquihue Lake were once within the range of Chono nomadism. The Chono people met Europeans for the first time when the naval expedition of Francisco de Ulloa arrived at their lands in 1553. In the late 16th-century and early 17th-century there were various Spanish incursions aimed to bring Chono to the Spanish dominions of Chiloé. These incursions turned into outright slave raids following the 1608 decree of King Philip III of Spain that legalized slavery of "indigenous rebels". Interest in the Chono lands arose again in the 1740s when the Spaniards learned about the wreck of the British warship HMS Wager on Wager Island in western Patagonia. As a result of a corsair and pirate menace the Spanish authorities were ordered to depopulate the archipelagos of Chono and Guaiteca to deprive their enemies of any eventual support from the native populations. This then led to the transfer of population to Chiloé Archipelago in the north while some Chono moved south of Taitao Peninsula, effectively depopulating the territory. The Chono in Chiloé ended up being absorbed by the mestizo and indigenous Huilliche population there. The Chono largely disappear from the historical record after the 18th century, but sporadic references remained. Inhabitants in the island of Laitec, which has strong historical links to the Chono, have an indigenous genetic admixture averaging 80%. The custom of the inhabitants of Melinka to bring dogs on board in their travels may be rooted in Chono traditions.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_PAPEETE', 			'Papeete' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_PAPEETE_ADJ', 			'Tahitian' UNION ALL
SELECT 'TXT_KEY_CIV5_PAPEETE_TEXT', 				'Tahiti, the largest island in French Polynesia, was settled in about 200 BCE, after a long migration from South East Asia or Indonesia, via the Fijian, Samoan and Tongan Archipelagos. This emigration, across several hundred kilometres of ocean, was made possible by using outrigger canoes that were up to twenty or thirty meters long and could transport families and domestic animals. [NEWLINE][NEWLINE]Tahitian society was composed of chiefdoms and territories based on kinship and military power among various clans. A clan was led by a chief (Ali''i rahi), nobles (Ari''i) and lesser chiefs. This culture flourished, and Tahiti became a center of Polynesian navigation and spirituality, characterized by the construction of marae (temples) for religious ceremonies. [NEWLINE]European contact began in the 18th century with the arrival of British explorers, including Samuel Wallis in 1767 and James Cook in 1769, followed by the French. These encounters brought dramatic changes, including the introduction of Christianity, new technologies, and diseases that significantly impacted the local population. [NEWLINE][NEWLINE]By the mid-19th century, Tahiti fell under French control, becoming a French protectorate in 1842 and later an official colony in 1880. The French influence brought infrastructure development, but it also suppressed traditional Tahitian culture. Despite periods of resistance, French Polynesia, including Tahiti, became an overseas territory of France in 1946, granting its residents French citizenship. [NEWLINE]Today, Tahiti maintains a distinct blend of Polynesian traditions and French cultural elements, with its economy reliant on tourism, black pearl farming, and French governmental support. The island is celebrated for its vibrant cultural heritage, stunning natural beauty, and a history that continues to shape its modern identity.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MANGAAS', 			'Mangaas' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_MANGAAS_ADJ', 			'Vanuatu' UNION ALL
SELECT 'TXT_KEY_CIV5_MANGAAS_TEXT', 				'Vanuatu was first settled by the Lapita culture, who settled around 3300 years ago. They brought with them their notable pottery, and marks of their habitation have been found on Efate, Malakula, and Aore. From Vanuatu they sailed to Fiji and Samoa. Over time however the unity of the Lapita weakened, and eventually Vanuatu became isolated from the rest of Melanesia. Vanuatu was first visited in 1606 by Pedro Fernandes de Queirós, who believed he had landed on "Terra Australis" and claimed the islands for Spain. However Spanish influence soon faded and the Spanish left the islands. Europeans did not again visit Vanuatu until 1768, with the visit of Louis Antoine de Bougainville. James Cook named Vanuatu the "New Hebrides" when visiting in 1774, and was the name used until independence.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_TARTESSOS', 			'Tartessos' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_TARTESSOS_ADJ', 			'Tartessian' UNION ALL
SELECT 'TXT_KEY_CIV5_TARTESSOS_TEXT', 				'Tartessos was an ancient civilization in the southern Iberian Peninsula, flourishing between the 9th and 6th centuries BCE in what is now modern-day Andalusia, Spain. Known as a wealthy and sophisticated society, Tartessos is often associated with the region around the Guadalquivir River. Its people were skilled in metallurgy, producing gold, silver, and bronze, which made them renowned in the Mediterranean world. Tartessos engaged in trade with Phoenician settlers who arrived around 1100 BCE, introducing Eastern cultural and technological influences. The civilization''s prominence is referenced in Greek and Roman sources, with legends describing it as a land of immense wealth ruled by a semi-mythical king, often identified as Argantonios. [NEWLINE][NEWLINE]By the 6th century BCE, Tartessos began to decline, possibly due to internal instability, the rising power of Carthage, and shifts in Mediterranean trade routes. Archaeological evidence and ancient texts suggest its society was eventually absorbed or displaced by other Iberian cultures. Though its exact location remains uncertain, some scholars link Tartessos to Atlantis myths due to its sudden disappearance. Modern research continues to uncover artifacts and sites that shed light on this enigmatic civilization, revealing its role as a cultural and economic bridge between the ancient Mediterranean and the indigenous peoples of Iberia.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_AGADEZ', 				'Agadez' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_AGADEZ_ADJ', 				'Agadez' UNION ALL
SELECT 'TXT_KEY_CIV5_AGADEZ_TEXT', 					'The Sultanate of Aïr, was a historic kingdom located in the Aïr Mountains region of present-day Niger. It emerged in the 15th century and played a prominent role in the Saharan trade networks. [NEWLINE]The Sultanate of Air was founded by the Tuareg people, who were nomadic herders and traders in the region. The sultans of Air, known as the Amenokal, held significant political and religious authority over the Tuareg tribes in the area. They governed from the city of Agadez, which served as the capital of the sultanate. [NEWLINE]The sultans of Air controlled important trade routes that linked the Sahara Desert to West Africa and North Africa. They facilitated the exchange of goods, including salt, gold, ivory, slaves, and other commodities. The sultanate grew wealthy and powerful due to its control over these lucrative trade routes. [NEWLINE]Throughout its history, the Sultanate of Air faced various challenges from neighboring empires and states. It often had to navigate alliances and conflicts with the Songhai Empire, the Fulani states, and other regional powers. [NEWLINE]During the 19th century, the sultanate came into contact with European colonial powers. It initially resisted French colonial encroachment but eventually succumbed to French influence. In 1904, the Sultanate of Air officially became part of the French colonial empire. [NEWLINE]After the colonization, the traditional power of the sultans diminished, but they retained some influence within the framework of the colonial administration. The region became part of the larger French West Africa and later Niger after gaining independence in 1960. [NEWLINE]Today, the Sultanate of Air holds cultural and historical significance for the Tuareg people and the nation of Niger. The Tuareg continue to maintain their unique cultural traditions, including music, craftsmanship, and a distinctive nomadic lifestyle. The city of Agadez remains an important cultural center and a UNESCO World Heritage Site, known for its historic architecture and role in Tuareg heritage.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_GONUR', 				'Gonur Depe' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_GONUR_ADJ', 				'Oxus' UNION ALL
SELECT 'TXT_KEY_CIV5_GONUR_TEXT', 					'The Oxus Civilization, also known as the Bactria-Margiana Archaeological Complex (BMAC), was a Bronze Age culture that flourished between roughly 2300 and 1700 BCE in Central Asia, spanning modern-day Turkmenistan, Uzbekistan, northern Afghanistan, and parts of Iran. Centered around the fertile oases of the Murghab and Amu Darya (Oxus) rivers, it developed advanced urban settlements characterized by fortified cities, monumental architecture, intricate metalwork, and vibrant trade networks linking Mesopotamia, the Indus Valley, and the Iranian Plateau. The Oxus people practiced irrigation-based agriculture and maintained a rich material culture featuring distinctive ceramics, seals, and religious artifacts that suggest complex social and spiritual systems. Though the civilization eventually declined, likely due to environmental changes, shifts in trade routes, and migrations of Indo-Iranian peoples, its influence persisted, contributing to the cultural foundations of later Central Asian and Persian civilizations. Oxus sites were discovered and named by the Soviet archaeologist Viktor Sarianidi during the period 1969-1979, when he was excavating in northern Afghanistan.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ISCA', 				'Isca' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_ISCA_ADJ', 				'Dumnonian' UNION ALL
SELECT 'TXT_KEY_CIV5_ISCA_TEXT', 					'Dumnonia, also known as Dyfneint, was a medieval kingdom located in what is now Cornwall and parts of Devon in southwestern Britain. It existed from the 5th to the 9th century CE and was associated with the Celtic Dumnonii tribe. [NEWLINE]The history of Dumnonia is not extensively documented, but it is believed to have been established in the post-Roman period, as the Roman influence in Britain waned. The Dumnonii, a Celtic people, likely retained control over the region after the Roman withdrawal and continued to maintain their own cultural and political identity. [NEWLINE]Dumnonia was a largely rural and agricultural society, with its population engaged in farming, fishing, and trading. It had close ties with other Celtic regions, such as Wales and Brittany, and maintained cultural and linguistic connections with them. [NEWLINE]The kingdom of Dumnonia faced various external pressures throughout its existence. It was frequently subject to invasions and conflicts with neighboring kingdoms, including the Anglo-Saxons who were expanding their territories in Britain. The Anglo-Saxon invasions eventually led to the fragmentation and decline of Dumnonia. [NEWLINE]By the 9th century, Dumnonia had been absorbed or incorporated into the expanding Kingdom of Wessex, ruled by the Anglo-Saxon dynasty. The integration of Dumnonia into the larger Wessex kingdom marked the end of the distinct political entity of Dumnonia. [NEWLINE]Nevertheless, the cultural legacy of Dumnonia endured in Cornwall and its neighboring regions. The Cornish language, closely related to Welsh and Breton, continued to be spoken in parts of Cornwall until the late medieval period. Cornish folklore, traditions, and place names also bear traces of the ancient Dumnonian culture. [NEWLINE]In recent years, there has been a revival of interest in Cornish identity and culture, with efforts to preserve and revive the Cornish language and promote awareness of Dumnonian heritage. Today, Cornwall maintains a distinct cultural identity within the United Kingdom, and Dumnonia is recognized as an important part of its historical legacy.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SA_HUYN', 			'Sa Huynh' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_SA_HUYN_ADJ', 			'Sa Huynh' UNION ALL
SELECT 'TXT_KEY_CIV5_SA_HUYN_TEXT', 				'The Sa Huỳnh culture was an ancient Iron Age civilization that thrived in central and southern Vietnam from around 1000 BCE to 200 CE, predating the rise of early Vietnamese states. It is renowned for its distinctive jar burial practices, intricate bronze and iron tools, and highly decorated ceramics, which indicate advanced craftsmanship and a complex society. The Sa Huỳnh people engaged in coastal and inland trade, connecting with regions across Southeast Asia, including the Philippines, Indonesia, and Thailand, as evidenced by the discovery of imported beads, shells, and other artifacts. Their society appears to have been organized into small communities with strong spiritual and ritual traditions, including ancestor worship and elaborate funerary rites. The culture gradually evolved into or influenced subsequent Vietic and Champa civilizations, leaving a lasting legacy in the archaeology and cultural history of Vietnam.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SHURI', 				'Shuri' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_SHURI_ADJ', 				'Ryukyuan' UNION ALL
SELECT 'TXT_KEY_CIV5_SHURI_TEXT', 					'The Ryukyu Kingdom, located in the Ryukyu Islands (modern-day Okinawa Prefecture, Japan), was an independent kingdom from the 15th to the 19th century. Unified in 1429 under King Shō Hashi, it emerged as a thriving maritime state, leveraging its strategic location to establish extensive trade networks across East and Southeast Asia, including China, Japan, Korea, and Siam. The kingdom''s cultural identity was deeply influenced by these interactions, blending Chinese Confucian ideals, Japanese traditions, and Southeast Asian influences, creating a unique Ryukyuan culture. Tributary relations with China''s Ming and Qing Dynasties played a central role in its political stability and access to trade, while its position as a neutral intermediary facilitated its prosperity during times of regional conflict. [NEWLINE][NEWLINE]In 1609, the Ryukyu Kingdom was invaded by Japan''s Satsuma Domain, leading to its vassal status while maintaining nominal independence to continue its tribute to China. This dual allegiance defined the kingdom''s later history until 1879, when Japan formally annexed the Ryukyu Islands, establishing Okinawa Prefecture during the Meiji Restoration. This transition marked the end of the kingdom and led to significant cultural assimilation and political integration into Japan. Despite this, Ryukyuan traditions, language, and identity endure, reflecting the region''s rich historical legacy as a bridge between different cultures.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_GEORGETOWN', 			'Georgetown' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_GEORGETOWN_ADJ', 			'Guyanese' UNION ALL
SELECT 'TXT_KEY_CIV5_GEORGETOWN_TEXT', 				'Guyana, located on the northern coast of South America, has a rich history shaped by its indigenous heritage and colonial encounters. Long before European arrival, the region was inhabited by Amerindian groups, including the Arawaks and Caribs, who developed sophisticated societies based on fishing, hunting, and agriculture. Dutch settlers were the first Europeans to establish trading posts and colonies in the area during the early 17th century. By the 18th century, control passed to the British, who consolidated three Dutch colonies into British Guiana in 1831. The plantation economy, based on sugar and other crops, relied heavily on African slave labor until slavery was abolished in 1834. This led to the importation of indentured laborers from India, China, and Portugal, profoundly shaping Guyana''s cultural and demographic landscape. [NEWLINE][NEWLINE]Guyana gained independence from British rule in 1966 and became a republic in 1970. Post-independence, the nation experienced political and economic challenges, including ethnic tensions between its two largest groups, Indo-Guyanese and Afro-Guyanese, rooted in its colonial labor systems. These tensions have played a significant role in the country''s politics. Despite its struggles, modern Guyana has emerged as a nation rich in natural resources, with newfound oil reserves positioning it for rapid economic transformation. Its diverse cultural heritage and Amazonian biodiversity contribute to its unique national identity, reflecting its complex history and vibrant society.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_VALJALA', 			'Valjala' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_VALJALA_ADJ', 			'Oeselian' UNION ALL
SELECT 'TXT_KEY_CIV5_VALJALA_TEXT', 				'The Oeselians were a seafaring and warrior people inhabiting the island of Saaremaa (Oesel in historical texts) in present-day Estonia during the Viking Age and the early medieval period. Renowned for their maritime prowess, they engaged in trade, piracy, and raids across the Baltic Sea. Early sources like the works of Tacitus and Scandinavian sagas reference their strategic position and influence in the region. The Oeselians built stronghold villages and participated in naval expeditions, often collaborating with or challenging other Baltic tribes and Scandinavian raiders. Their craftsmanship, particularly in shipbuilding, enabled them to assert dominance in regional waters. [NEWLINE][NEWLINE]By the 13th century, the Christianization and crusades in the Baltic region brought the Oeselians into conflict with the Teutonic Order and the Livonian Brothers of the Sword. After decades of resistance, including notable battles like the siege of the Oeselian stronghold in 1227, they were eventually subdued and converted to Christianity. Despite this, their distinct cultural identity persisted for centuries. The legacy of the Oeselians endures in Saaremaa''s archaeological sites and in the island''s role as a historical crossroads of Nordic and Baltic civilizations. Their maritime traditions remain emblematic of the broader Viking and Baltic seafaring heritage.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_WAITIKUBULI', 		'Wai''tukubuli' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_WAITIKUBULI_ADJ', 		'Kalinago' UNION ALL
SELECT 'TXT_KEY_CIV5_WAITIKUBULI_TEXT', 			'The Kalinago, also known as the Island Caribs or simply Caribs, are an indigenous people of the Lesser Antilles in the Caribbean. At the time of Spanish contact, the Caribs were one of the dominant groups in the Caribbean, which owes its name to them. They lived throughout the Windward Islands, Dominica, and possibly the southern Leeward Islands. Historically it was thought their ancestors were mainland Caribs who conquered the islands from their previous inhabitants, known as the Igneri.[NEWLINE][NEWLINE]In the early colonial period, the Caribs had a reputation as warriors who raided neighboring islands. Early Europeans claimed that they practiced cannibalism - the word "cannibal" derives from a corruption of their name. Today, the Caribs and their descendants continue to live in the Antilles. [NEWLINE][NEWLINE]Like most of the indigenous peoples of the New World, the Kalinago suffered greatly from European Colonization of the Americas European conquest, and their descendants are now scattered throughout the Caribbean and South America, with the largest group living on the island of Dominica where the British established a reservation for them.[NEWLINE][NEWLINE]Today, Carib make effort to preserve their culture and educate their children and others about their traditions, maintaining their identity while at the same time being part of the contemporary society.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_LUANGPRABANG', 		'Luang Prabang' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_LUANGPRABANG_ADJ', 		'Lao' UNION ALL
SELECT 'TXT_KEY_CIV5_LUANGPRABANG_TEXT', 			'Although archaeological evidence indicates that settlers along the Mekong had learned agriculture, metallurgy, and pottery making by 3000 BC, little is known about the early history of the land that today bears the name of Laos. The lowland Lao are believed to be the descendants of Thai tribes that were pushed southward in the 8th century. According to tradition, the kingdom called Lan Xang ("a million elephants") was established in 756 by King Thao Khoun Lo. In 1353, it was reunified by Fa-Ngoum, who had been raised at the court of Angkor in Kampuchea and returned with a force of Khmer troops. He is also credited with the introduction of Hinayana Buddhism into Laos. Lan Xang waged intermittent wars with the Khmers, Burmese, Vietnamese, and Thai and developed an effective administrative system, an elaborate military organization, and an active commerce with neighboring countries. In 1707, internal dissensions brought about a split of Lan Xang into two kingdoms, Luang Prabang in the north (present-day upper Laos) and Vientiane in the south (lower Laos). Strong neighboring states took advantage of this split to invade the region.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_KANONWALOHALE', 		'Kanonwalohale' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_KANONWALOHALE_ADJ', 		'Oneida' UNION ALL
SELECT 'TXT_KEY_CIV5_KANONWALOHALE_TEXT', 			'The Oneida people, one of the original five nations of the Haudenosaunee Confederacy (also known as the Iroquois Confederacy), have a long history rooted in the northeastern woodlands of what is now the United States. Traditionally, they inhabited the area around modern-day central New York State. Known as the "People of the Standing Stone," the Oneida played a central role in the confederacy, which was established to maintain peace and unity among the member nations through the Great Law of Peace. They practiced a matrilineal society, governed by clan mothers and a council of chiefs, and sustained themselves through agriculture, hunting, and fishing. European contact in the 17th century introduced significant changes, including trade relationships, the spread of Christianity, and conflicts during the colonial period. [NEWLINE][NEWLINE]During the American Revolution, the Oneida were unique among the Haudenosaunee in siding with the American colonists, providing crucial support, including at the pivotal Battle of Oriskany. However, this alliance came at a high cost, as their lands and villages were devastated during the war. Post-war treaties often stripped them of land, leading to displacement and marginalization. By the 19th century, many Oneida had been relocated to Wisconsin, Ontario, and other areas, though some remained in New York. Today, the Oneida Nation is revitalizing its culture, language, and traditions, with communities in the United States and Canada serving as stewards of their heritage and playing significant roles in promoting sovereignty and self-determination.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_PSKOV', 				'Pskov' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_PSKOV_ADJ', 				'Pskov' UNION ALL
SELECT 'TXT_KEY_CIV5_PSKOV_TEXT', 					'The Pskov Republic was a medieval Rus'' polity centered on the city of Pskov in what is now northwestern Russia. It emerged as an autonomous region in the 12th century, growing out of its ties to the Novgorod Republic. By the 14th century, Pskov achieved greater independence, establishing itself as a significant trading hub along the Hanseatic League routes. Governed through a veche (popular assembly), the republic practiced a form of participatory democracy, with elected officials including a prince, who served as a military leader and judicial figure, under strict veche oversight. Pskov''s strategic location and well-fortified architecture, such as the iconic Pskov Kremlin (Krom), enabled it to withstand numerous foreign invasions, particularly from the Livonian Order and Lithuania. [NEWLINE][NEWLINE]Despite its autonomy, the Pskov Republic faced growing pressure from the centralizing forces of Moscow. In 1510, Grand Prince Vasili III of Moscow annexed Pskov, ending its independence and incorporating it into the centralized Russian state. The annexation marked the decline of Pskov''s distinct political identity, though its architectural and cultural heritage continued to influence Russian history. Today, Pskov''s medieval monuments, including churches and fortifications, serve as reminders of its rich legacy as a center of trade, governance, and resilience during the turbulent medieval period.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_YAMBIO', 				'Yambio' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_YAMBIO_ADJ', 				'Zande' UNION ALL
SELECT 'TXT_KEY_CIV5_YAMBIO_TEXT', 					'The Azande (plural of "Zande" in the Zande language) are an ethnic group of North Central Africa. They live primarily in the northeastern part of the Democratic Republic of the Congo, in south-central and southwestern part of South Sudan, and in southeastern Central African Republic. In the early 19th century, the Bandia people ruled over the Vungara and the two groups became the Azande people. They lived in the savannas of what is now the southeastern part of Central African Republic. After the death of a king, the king''s sons would fight for succession. The losing son would often establish kingdoms in neighbouring regions, making the Azande kingdom spread eastward and northward. Sudanese raids halted some of northward expansion later in the 19th century. The Azande became divided by Belgium, France, and Anglo-Egyptian Sudan. The word Azande means "the people who possess much land", and refers to their history as conquering warriors. Variant spellings include Adio, Zande, Zandeh, A-Zandeh and Sandeh. The name Niam-Niam was frequently used by foreigners to refer to the Azande in the 18th and early 19th century. This name is probably of Dinka origin, and means "great eaters" in that language, supposedly referring to cannibalistic propensities. This name for the Azande was in use by other tribes in South Sudan, and later adopted by westerners.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_PAVIA', 				'Pavia' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_PAVIA_ADJ', 				'Lombard' UNION ALL
SELECT 'TXT_KEY_CIV5_PAVIA_TEXT', 					'The Lombards or Langobards were a Germanic tribe who ruled Italy from 568 to 774. The Lombards descended from a small tribe called the Winnili, who dwelt in southern Scandinavia before migrating to seek new lands. By the end of the 5th century they had moved into the area roughly coinciding with modern Austria north of the Danube river. The Lombard king Audoin defeated the Gepid leader Thurisind in 551 or 552; his successor Alboin eventually destroyed the Gepids at the Battle of Asfeld in 567.Following this victory, Alboin decided to lead his people to Italy, which had become severely depopulated and devastated after the long Gothic War (535-554) between the Byzantine Empire and the Ostrogothic Kingdom there. The Lombards were joined by numerous Saxons, Heruls, Gepids, Bulgars, Thuringians, and Ostrogoths, and their invasion of Italy was almost unopposed. By late 569 they had conquered all the principal cities north of the Po River except Pavia, which fell in 572. At the same time, they occupied areas in central and southern Italy. They established a Lombard Kingdom in Italy, later named Regnum Italicum ("Kingdom of Italy"), which reached its zenith under the 8th-century ruler Liutprand. In 774, the Kingdom was conquered by the Frankish King Charlemagne and integrated into his Empire. However, Lombard nobles continued to rule parts of the Italian peninsula well into the 11th century when they were conquered by the Normans and added to their County of Sicily. Their legacy is apparent in the regional name, Lombardy.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_GHAZNI', 				'Ghazni' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_GHAZNI_ADJ', 				'Zunbil' UNION ALL
SELECT 'TXT_KEY_CIV5_GHAZNI_TEXT', 					'The Zunbil dynasty was a ruling dynasty in the region of Zabulistan, in present-day southern Afghanistan, flourishing from the 7th to the 9th centuries CE. The Zunbils are named after their principal deity, Zun, a sun god worshipped in their temples, reflecting the syncretic pre-Islamic religious traditions of the region, which included Hindu, Buddhist, and local animist influences. The dynasty exercised semi-independent control while navigating the political pressures of neighboring powers such as the Sasanian Empire, the Arab Caliphates, and the Kabul Shahis. The Zunbils maintained fortified cities and a network of trade routes connecting the Indian subcontinent and Central Asia, contributing to regional commerce and cultural exchange. Their rule gradually ended with the expansion of Islam in the 9th century, but their legacy persists in the historical and religious memory of southern Afghanistan.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_UJJAIN', 				'Kannauj' UNION ALL  -- Ujjain
SELECT 'TXT_KEY_CITYSTATE_UJJAIN_ADJ', 				'Gurjara-Pratihara' UNION ALL
SELECT 'TXT_KEY_CIV5_UJJAIN_TEXT', 					'The Gurjara-Pratihara dynasty was a prominent Indian dynasty that ruled much of northern and western India from the 8th to the 11th centuries CE, known for its role in resisting Arab invasions and fostering a period of political stability and cultural growth. Originating in the region of modern-day Rajasthan and Gujarat, the Pratiharas established their capital at Kannauj, which became a major center of administration, trade, and art. The dynasty reached its peak under rulers such as Nagabhata II and Mihira Bhoja, who expanded their territory and patronized Hindu temples and learning, contributing to the flourishing of early medieval Indian culture. The Gurjara-Pratiharas were also significant in the tripartite struggle with the Palas of Bengal and the Rashtrakutas of the Deccan for control of northern India. Their decline in the 11th century, due to internal fragmentation and external invasions, paved the way for the rise of regional kingdoms, but their legacy endures in architecture, inscriptions, and the consolidation of northern Indian political identity.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SUSA', 				'Susa' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_SUSA_ADJ', 				'Elam' UNION ALL
SELECT 'TXT_KEY_CIV5_SUSA_TEXT', 					'Elam was an ancient civilization centered in the far west and southwest of modern-day Iran, stretching from the lowlands of what is now Khuzestan and Ilam Province as well as a small part of southern Iraq. The modern name Elam stems from the Sumerian transliteration elam(a), along with the later Akkadian elamtu, and the Elamite haltamti. Elamite states were among the leading political forces of the Ancient Near East. In classical literature, Elam was also known as Susiana, a name derived from its capital Susa. Elam was part of the early urbanization during the Chalcolithic period. The emergence of written records from around 3000 BC also parallels Sumerian history, where slightly earlier records have been found. In the Old Elamite period (Middle Bronze Age), Elam consisted of kingdoms on the Iranian plateau, centred in Anshan, and from the mid-2nd millennium BC, it was centred in Susa in the Khuzestan lowlands. Its culture played a crucial role during the Persian Achaemenid dynasty that succeeded Elam, when the Elamite language remained among those in official use. Elamite is generally considered a language isolate unrelated to any other languages.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_BOINNE', 				'Brú na Bóinne' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_BOINNE_ADJ', 				'Boyne' UNION ALL
SELECT 'TXT_KEY_CIV5_BOINNE_TEXT', 					'Brú na Bóinne ("Palace of the Boyne" or more properly "Valley of the Boyne") or Boyne valley tombs, is an area in County Meath, Ireland, located in a bend of the River Boyne. It contains one of the world''s most important prehistoric landscapes dating from the Neolithic period, including the large Megalithic passage graves of Knowth, Newgrange and Dowth as well as some 90 additional monuments. The archaeological culture associated with these sites is called the "Boyne culture". Since 1993, the site has been a World Heritage Site designated by UNESCO, known since 2013 as "Brú na Bóinne - Archaeological Ensemble of the Bend of the Boyne".' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_BUKHARA', 			'Bukhara' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_BUKHARA_ADJ', 			'Bukharan' UNION ALL
SELECT 'TXT_KEY_CIV5_BUKHARA_TEXT', 				'The Shaybanids, or Shibanids, (or more accurately the Abu''l-Khayrid-Shibanids) were a Persianized Turko-Mongol dynasty in Central Asia who ruled over most of modern-day Kazakhstan, much of Uzbekistan, and parts of southern Russia (including Siberia) in the 15th century. They were the patrilineal descendants of Shiban, the fifth son of Jochi and grandson of Genghis Khan. Until the mid-14th century, they acknowledged the authority of the descendants of Shiban''s brothers Batu Khan and Orda Khan, such as Oz Beg Khan. The Shaybanids originally led the grey horde southeast of the Urals (also known as the Uzbegs, after the Uzbeks), and converted to Islam in 1282. At its height, the khanate included parts of modern-day Afghanistan and other parts of Central Asia.[NEWLINE][NEWLINE]Another state ruled by the Shaybanids was the Khanate of Sibir, seizing the throne in 1563. Its last khan, Kuchum, was deposed by the Russians in 1598. He escaped to Bukhara, but his sons and grandsons were taken by the Tsar to Moscow, where they eventually assumed the surname of Sibirsky.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MUARO_JAMBI', 		'Muaro Jambi' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_MUARO_JAMBI_ADJ', 		'Srivijaya' UNION ALL
SELECT 'TXT_KEY_CIV5_MUARO_JAMBI_TEXT', 			'Muaro Jambi is an ancient archaeological site located in Jambi Province on the island of Sumatra, Indonesia. Believed to have flourished between the 7th and 13th centuries CE, it was a major center of the Buddhist Srivijaya Empire, which dominated maritime Southeast Asia during this period. Covering an area of approximately 12 square kilometers along the Batang Hari River, Muaro Jambi consists of at least 82 identified structures, including brick temples (candi), moats, canals, and habitation areas. It served as a hub for trade, culture, and education, attracting scholars and pilgrims from across the region, particularly from India and China. The site reflects strong Mahayana Buddhist influences and is believed to have played a role in spreading Buddhism throughout Southeast Asia. [NEWLINE][NEWLINE]The decline of Muaro Jambi is thought to have been linked to the fall of the Srivijaya Empire and the rise of other political powers such as the Javanese Majapahit Kingdom. Over time, the site was abandoned and largely forgotten, overgrown by dense jungle until rediscovery in the early 20th century. Today, Muaro Jambi is recognized as one of Indonesia''s most significant archaeological sites, offering valuable insights into the region''s ancient history and maritime networks. Efforts are ongoing to preserve and study its ruins, which stand as a testament to the cultural and economic achievements of the Srivijaya period.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_THOLING', 			'Tholing' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_THOLING_ADJ', 			'Guge' UNION ALL
SELECT 'TXT_KEY_CIV5_THOLING_TEXT', 				'Guge was a medieval kingdom located in western Tibet, flourishing between the 10th and 17th centuries CE, known for its distinctive Tibetan Buddhist culture, art, and architecture. Established after the collapse of the Tibetan Empire, Guge became a center of religious revival and artistic innovation, with rulers sponsoring the construction of monasteries, temples, and elaborate frescoes, particularly in the kingdom''s capital at Tsaparang. The kingdom played a key role in the spread of Buddhism in the region, attracting Indian and Nepalese scholars and artists who influenced its unique style. Guge also engaged in trade and diplomatic relations with neighboring Tibetan regions and beyond. Its decline began in the 17th century due to internal strife, invasions, and the expansion of the neighboring Ladakhi and Central Tibetan powers, leaving behind remarkable ruins and cultural heritage that continue to illustrate the kingdom''s historical significance in Tibetan history.'  UNION ALL
--=====================================================================
SELECT 'TXT_KEY_CITYSTATE_SAGALA', 				'Sagala' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SAGALA_ADJ', 				'Indo-Greek' UNION ALL
SELECT 'TXT_KEY_CIV5_SAGALA_TEXT', 					'The Indo-Greeks were a succession of Hellenistic rulers who established kingdoms in parts of present-day Afghanistan, Pakistan, and northwestern India between the 2nd century BCE and the early 1st century CE, following the fragmentation of Alexander the Great''s empire. Originating from the Greco-Bactrian Kingdom, they extended their control into the Indian subcontinent under kings such as Demetrius I and Menander I (Milinda), the latter famed for his dialogue with the Buddhist sage Nagasena recorded in the Milindapañha. The Indo-Greeks are renowned for blending Greek and Indian cultural, religious, and artistic traditions-visible in their bilingual coinage and early representations of the Buddha influenced by Greek realism. Their reign facilitated the spread of Hellenistic art and ideas into South Asia and contributed to the later development of Greco-Buddhist culture in Gandhara. Though eventually absorbed by Indo-Scythian and Kushan powers, the Indo-Greeks left an enduring legacy of cultural fusion between East and West.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_QARNAWU', 			'Qarnawu' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_QARNAWU_ADJ', 			'Minaean' UNION ALL
SELECT 'TXT_KEY_CIV5_QARNAWU_TEXT', 				'The Ma''in, also known as the Minaeans, were an ancient South Arabian people who flourished between the 8th and 2nd centuries BCE in what is now northern Yemen. Centered around their capital Qarnawu (modern-day Ma''in), they established one of the earliest and most prosperous kingdoms of ancient Arabia, thriving on trade along the incense routes that connected southern Arabia with the Mediterranean and Mesopotamia. The Ma''in controlled key caravan cities and formed alliances with neighboring kingdoms such as Saba and Qataban, facilitating the export of frankincense, myrrh, and spices. Their society was organized around powerful merchant families and councils rather than monarchs, reflecting a distinctive form of governance in the region. Although their influence declined with the rise of the Sabaean and later Himyarite kingdoms, the Ma''in left behind a rich legacy of inscriptions and archaeological remains that illuminate the early development of Arabian trade, language, and civilization.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_FITIUTA', 			'Fiti''uta' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_FITIUTA_ADJ', 			'Tui Manu''a' UNION ALL
SELECT 'TXT_KEY_CIV5_FITIUTA_TEXT', 				'Tui Manu''a was the title of the sovereign rulers of the Manu''a Islands, part of present-day American Samoa, and represents one of the oldest known chiefly dynasties in Polynesia. According to oral traditions and genealogies, the Tui Manu''a lineage dates back more than 2,000 years and was considered among the most sacred and prestigious titles in the ancient Samoan and wider Polynesian world. The Tui Manu''a were regarded as both political leaders and divine figures, with influence extending across the Samoan archipelago and possibly into neighboring island groups. The kingdom maintained its autonomy well into the 19th century, when the last recognized monarch, Tui Manu''a Elisara, ruled until 1909 before formally accepting U.S. authority under the Deeds of Cession that established American Samoa. Today, the legacy of the Tui Manu''a endures as a vital part of Samoan heritage, symbolizing indigenous governance, spiritual authority, and cultural continuity.' UNION ALL
--=====================================================================
SELECT 'TXT_KEY_CITYSTATE_ETENHIRITIPA', 		'Etenhiritipá' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ETENHIRITIPA_ADJ', 		'Xavante' UNION ALL
SELECT 'TXT_KEY_CIV5_ETENHIRITIPA_TEXT', 			'The Xavante are an indigenous people of central Brazil, primarily living in the cerrado region of Mato Grosso. Traditionally semi-nomadic hunter-gatherers and farmers, they are known for their strong warrior culture, elaborate initiation rituals, and distinctive body painting and adornments. The Xavante historically inhabited areas further east but were displaced westward during the 18th and 19th centuries due to colonial expansion. In the mid-20th century, they experienced forced contact with non-Indigenous society through government "pacification" campaigns, which brought disease and land loss but also led to the recognition of some of their territories. Today, they maintain a vibrant cultural identity, blending traditional practices with political activism to defend their land rights and autonomy, while facing ongoing challenges from deforestation, agribusiness, and environmental pressures.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MANGOLA', 			'Mang''ola' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MANGOLA_ADJ', 			'Hadza' UNION ALL
SELECT 'TXT_KEY_CIV5_MANGOLA_TEXT', 				'The Hadza, also known as Hadzabe, are an Indigenous hunter-gatherer people living around Lake Eyasi in northern Tanzania, and are considered one of the last remaining groups in the world to maintain a traditional foraging lifestyle. Their ancestry in the East African Rift Valley likely stretches back tens of thousands of years, linking them to some of the earliest human populations. The Hadza live in small, mobile bands and subsist on wild foods (such as tubers, berries, honey, and game)n without agriculture, herding, or permanent dwellings. Their egalitarian social structure emphasizes sharing, cooperation, and autonomy, with decisions made collectively and little hierarchy. Despite pressures from land encroachment, conservation zones, and modernization, the Hadza have resisted full assimilation and continue to embody a way of life closely connected to the rhythms of nature. Today, they are recognized both for their deep anthropological significance in understanding human origins and for their ongoing struggle to protect their ancestral lands and cultural autonomy.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MELGITAT', 			'Melgita''t' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MELGITAT_ADJ', 			'Beothuk' UNION ALL
SELECT 'TXT_KEY_CIV5_MELGITAT_TEXT', 				'The Beothuk were an Indigenous people of Newfoundland, Canada, who lived on the island for thousands of years before European contact, relying on fishing, hunting, and gathering to sustain themselves in the island''s coastal and forested environments. Known for their distinctive use of red ochre to paint their bodies, tools, and dwellings (a practice that gave rise to their name, meaning "the people") the Beothuk maintained a largely self-sufficient and isolated existence, avoiding direct contact with European settlers and fishermen who arrived from the 16th century onward. As colonial expansion, resource competition, and introduced diseases spread, the Beothuk were gradually displaced from their lands and deprived of access to vital food sources. By the early 19th century, their population had dwindled severely, and with the death of Shanawdithit in 1829, the Beothuk as a distinct people were declared extinct. However, their memory endures as a poignant symbol of cultural loss and the lasting impact of colonization in North America.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_KOTA_BATU', 			'Kota Batu' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_KOTA_BATU_ADJ', 			'Bruneian' UNION ALL
SELECT 'TXT_KEY_CIV5_KOTA_BATU_TEXT', 				'The Bruneian empire was a powerful maritime sultanate centered in present-day Brunei Darussalam that flourished from the 14th to the 17th centuries. Its rise began under early Muslim rulers who converted the region to Islam, consolidating power along the northern coast of Borneo. At its peak during the reign of Sultan Bolkiah ibni Sulaiman in the late 15th and early 16th centuries, the empire controlled large parts of Borneo and extended its influence over the Sulu Archipelago and parts of present-day Philippines. It thrived on trade in spices, camphor, and other regional goods, connecting Southeast Asia to the wider Muslim and Chinese trading worlds. The empire began to decline in the 17th century due to internal conflicts, succession disputes, European colonial expansion, and the rise of rival powers. By the 19th century, it had lost most of its territories, though the sultanate persisted, eventually becoming the modern state of Brunei.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_PIR_E_SABZ', 			'Pir-e Sabz' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_PIR_E_SABZ_ADJ', 			'Sassanid' UNION ALL
SELECT 'TXT_KEY_CIV5_PIR_E_SABZ_TEXT', 				'Pir-e Sabz is a village in the Yazd Province of Iran. The village consists of a "pir" (a pilgrimage site for Zoroastrians) perched beneath a towering cliff face in the desert of central Iran. It is the most sacred of the mountain shrines of Zoroastrianism, which was formerly the majority and official religion of the Iranian nation. Each year, from 14 to 18 June, thousands of Zoroastrians from Iran and India, among other countries, flock to the site''s fire temple.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MANGAZEYA', 			'Mangazeya' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MANGAZEYA_ADJ', 			'Mangazeya' UNION ALL
SELECT 'TXT_KEY_CIV5_MANGAZEYA_TEXT', 				'Mangazeya was a prosperous Russian trading town founded in 1601 on the Taz River in northwestern Siberia, near the Arctic Circle. It became a key outpost during Russia''s eastward expansion, serving as a hub for the lucrative ivory (walrus tusks) and fur trade, especially sable, and attracting merchants from across Russia. Often called the "golden city of the North", Mangazeya grew rapidly thanks to its strategic position on northern river routes linking European Russia with Siberia. However, its prosperity also drew unwanted foreign interest, particularly from European powers, which worried Moscow. In response, the government eventually closed the northern sea route and restricted access to the town in 1619. A devastating fire in 1642 and shifting trade routes led to its decline, and by the late 17th century, it was abandoned. Today, Mangazeya survives mainly through archaeological remains and legends of its former wealth.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_STANDING_ROCK', 		'Standing Rock' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_STANDING_ROCK_ADJ', 			'Sioux' UNION ALL
SELECT 'TXT_KEY_CIV5_STANDING_ROCK_TEXT', 				'The Sioux are a Native American people in North America, traditionally belonging to the Oceti Sakowin, i.e. the Great Sioux Nation or "Seven Fires Council". They can be subdivided into three major divisions based on dialect and culture: the Santee, the Yankton-Yanktonai, and the Lakota. Gradually migrating west from Minnesota, the Sioux became nomads of the plains, taking advantage of horses which were originally brought to the Americas by the Spanish. They relied on buffalo hunting and lived in tipis that can be disassembled and packed away quickly when people need to relocate and can be reconstructed quickly upon settling in a new area, allowing for great mobility across the plains.  They first came into contact with Europeans during the 17th century, which would begin a series of conflicts as European settlers continued to push west onto Sioux lands, that culminated with the discovery of gold in the Black Hills in 1874 and the subsequent Great Sioux War of 1876. After three major wars and numerous other skirmishes, the battle of Wounded Knee in December 1890 marked the end of Sioux resistance as approximately 300 of Lakota men, women, and children were massacred by US troops. Today, the majority of the Sioux live at the 2,782 square mile Pine Ridge Reservation in southwestern South Dakota.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_LANTAU', 				'Lantau' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_LANTAU_ADJ', 				'Lantau' UNION ALL
SELECT 'TXT_KEY_CIV5_LANTAU_TEXT', 					'Lantau Island is the largest island in Hong Kong and has long held strategic importance due to its location at the mouth of the Pearl River Delta, serving as both a fishing hub and a maritime gateway to southern China. In the early 19th century, it was a stronghold of the notorious pirate queen Ching Shih, who commanded one of the most powerful pirate fleets in history. Leading the Red Flag Fleet (Hóngqí Bang), an alliance of 400 ships and more than 40,000 pirates at its height, Ching Shih controlled much of the South China Sea, including the waters around Lantau Island, Wanshan Archipelago, and the Leizhou Peninsula. Her dominance disrupted regional trade and challenged Qing dynasty naval forces and Western powers alike. Eventually, in 1810, she negotiated an unprecedented amnesty with the Qing government, retiring with her wealth and freedom intact. Today, Lantau Island is better known for its natural beauty, cultural landmarks like the Tian Tan Buddha, and its transformation into a modern hub featuring Hong Kong International Airport and Disneyland.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_CO_LOA', 				'Co Loa' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_CO_LOA_ADJ', 				'Viet' UNION ALL
SELECT 'TXT_KEY_CIV5_CO_LOA_TEXT', 					'Co Loa, an ancient citadel located near modern-day Hanoi, Vietnam, is considered one of the earliest and most significant political and military centers in Vietnamese history. Believed to have been built in the 3rd century BCE by King An Duong Vuong of the Au Lac kingdom, it was renowned for its spiral-shaped earthen ramparts and advanced defensive design. Centuries later, during the first century CE, Co Loa and the surrounding region became a focal point of resistance during the Trung Sisters'' Rebellion (40-43 CE), when Trung Trac and Trung Nhi led a major uprising against Han Chinese rule. Their revolt briefly restored Vietnamese independence and established them as national heroines, symbolizing courage and resistance against foreign domination. Trung Trac became the first queen in the history of Vietnam, although her reign lasted only 3 years.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DELHI', 				'Delhi' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DELHI_ADJ', 				'Delhi' UNION ALL
SELECT 'TXT_KEY_CIV5_DELHI_TEXT', 					'The Delhi Sultanate, established in 1206, was a series of Muslim dynasties that ruled much of northern India until 1526, marking a transformative era in Indian history characterized by the introduction of Islamic governance, architecture, and culture. It began with the Mamluk (Slave) dynasty founded by Qutb al-Din Aibak and later included the Khalji, Tughlaq, Sayyid, and Lodi dynasties. Among its rulers, Razia Sultan (aka Raziyat al-Din) stands out as the first and only female monarch to sit on the throne of Delhi, reigning from 1236 to 1240. The daughter of Sultan Iltutmish, Razia was known for her intelligence, administrative skill, and progressive vision, challenging gender norms by dressing as a man and leading armies in person. Despite her competence, she faced strong opposition from conservative nobles unwilling to accept a female ruler, ultimately leading to her overthrow and death.';

